    this.keys = { left:false, right:false, up:false, down:false };
    this.tiltX = 0; // current board tilt angle around X axis (forward/backward)
    this.tiltZ = 0; // current board tilt angle around Z axis (left/right)
    this.targetTiltX = 0;
    this.targetTiltZ = 0;
    this.ballVelX = 0;
    this.ballVelZ = 0;
    this.ballX = 0; // ball position in board-local space
    this.ballZ = 0;
    this.ballFalling = false;
    this.ballFallY = 0;
    this.ballFallVelY = 0;
    this.gems3D = [];
    this.goal3D = null;
    this.wallAABBs = []; // {minX, maxX, minZ, maxZ}
    this.holeSet = new Set(); // "cx,cz"
    this.boardW = 0;
    this.boardH_world = 0;

    this.initRenderer();
    this.initScene();
    this.initLighting();
    this.initInputs();
    this.loadLevel(0);
    this.animate(0);
    window.game = this;
  }

  // ── RENDERER SETUP ──────────────────────────────────────────────────
  initRenderer() {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.outputEncoding = THREE.sRGBEncoding;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.1;
    document.getElementById('canvas-container').appendChild(this.renderer.domElement);

    window.addEventListener('resize', () => {
      this.camera.aspect = window.innerWidth / window.innerHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(window.innerWidth, window.innerHeight);
    });
  }

  initScene() {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x070710);
    this.scene.fog = new THREE.Fog(0x070710, 30, 80);

    // Camera
    this.camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 200);
    this.cameraBasePos = new THREE.Vector3(0, 18, 14);
    this.camera.position.copy(this.cameraBasePos);
    this.camera.lookAt(0, 0, 0);

    // Board group (everything tilts with the board)
    this.boardGroup = new THREE.Group();
    this.scene.add(this.boardGroup);

    // Starfield background
    this.createStarfield();
  }

  createStarfield() {
    const geo = new THREE.BufferGeometry();
    const count = 800;
    const pos = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      pos[i*3]   = (Math.random()-0.5)*120;
      pos[i*3+1] = (Math.random()-0.5)*120;
      pos[i*3+2] = (Math.random()-0.5)*120;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const mat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.15, transparent:true, opacity:0.6 });
    this.scene.add(new THREE.Points(geo, mat));
  }

  initLighting() {
    // Ambient
    const ambient = new THREE.AmbientLight(0x8090b0, 0.5);
    this.scene.add(ambient);

    // Main directional (sunlight from above-left)
    const sun = new THREE.DirectionalLight(0xfff5e0, 1.6);
    sun.position.set(8, 20, 8);
    sun.castShadow = true;
    sun.shadow.mapSize.width  = 2048;
    sun.shadow.mapSize.height = 2048;
    sun.shadow.camera.near   = 0.5;
    sun.shadow.camera.far    = 80;
    sun.shadow.camera.left   = -20;
    sun.shadow.camera.right  = 20;
    sun.shadow.camera.top    = 20;
    sun.shadow.camera.bottom = -20;
    sun.shadow.bias = -0.001;
    this.scene.add(sun);
    this.sunLight = sun;

    // Fill light from below-right
    const fill = new THREE.DirectionalLight(0x4060ff, 0.3);
    fill.position.set(-6, -4, -8);
    this.scene.add(fill);

    // Point light near ball (moves with it) - added dynamically
    this.ballLight = new THREE.PointLight(0xffffff, 0.4, 6);
    this.scene.add(this.ballLight);
  }

  initInputs() {
    this.keys = {};
    window.addEventListener('keydown', e => {
      this.keys[e.code] = true;
      // Prevent scrolling
      if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)) e.preventDefault();
    });
    window.addEventListener('keyup', e => { this.keys[e.code] = false; });
    document.getElementById('btn-next-level').addEventListener('click', () => this.nextLevel());
  }

  // ── LEVEL LOADING ────────────────────────────────────────────────────
  loadLevel(idx) {
    if (idx >= LEVELS.length) { idx = LEVELS.length - 1; }
    this.currentLevel = idx;
    const lvl = LEVELS[idx];

    // Clear board
    while (this.boardGroup.children.length) {
      const child = this.boardGroup.children[0];
      this.boardGroup.remove(child);
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    }
    this.gems3D = [];
    this.wallAABBs = [];
    this.holeSet = new Set();
    this.particleSystems = [];

    const cols = lvl.cols;
    const rows = lvl.rows;
    this.boardCols = cols;
    this.boardRows = rows;
    this.boardW = cols * CELL;
    this.boardH_world = rows * CELL;

    // Helper: grid to world (board-local, centered)
    this.gridToWorld = (gx, gz) => ({
      x: (gx + 0.5) * CELL - this.boardW * 0.5,
      z: (gz + 0.5) * CELL - this.boardH_world * 0.5
    });

    // Build hole set
    (lvl.holes || []).forEach(([hx, hz]) => this.holeSet.add(`${hx},${hz}`));

    // ── FLOOR TILES ──────────────────────────────────────────────────
    this.buildFloor(lvl);

    // ── WALLS ────────────────────────────────────────────────────────
    this.buildWalls(lvl);

    // ── GEMS ─────────────────────────────────────────────────────────
    this.buildGems(lvl);

    // ── GOAL ─────────────────────────────────────────────────────────
    this.buildGoal(lvl);

    // ── BALL ─────────────────────────────────────────────────────────
    this.buildBall(lvl);

    // State reset
    this.tiltX = 0; this.tiltZ = 0;
    this.targetTiltX = 0; this.targetTiltZ = 0;
    this.boardGroup.rotation.set(0, 0, 0);
    this.ballVelX = 0; this.ballVelZ = 0;
    this.ballFalling = false;
    this.ballFallVelY = 0;
    this.gemsCollected = 0;
    this.totalGems = (lvl.gems || []).length;
    this.gemCollected = new Array(this.totalGems).fill(false);
    this.elapsedTime = 0;
    this.timerRunning = false;
    this.gameState = 'intro';

    // HUD
    document.getElementById('hud-level-val').textContent = idx + 1;
    this.updateHUD();

    // Hide overlays
    document.getElementById('overlay-complete').classList.remove('visible');
    document.getElementById('overlay-gameover').classList.remove('visible');

    // Level intro
    this.showLevelIntro(idx, lvl.name);
  }

  buildFloor(lvl) {
    const cols = lvl.cols, rows = lvl.rows;

    // Wood floor material (procedural texture)
    const floorTex = this.createWoodTexture(512, 512, '#c8902a', '#a06820');
    const floorMat = new THREE.MeshStandardMaterial({
      map: floorTex,
      roughness: 0.75,
      metalness: 0.0,
      color: 0xd4952e
    });

    // Hole edge material (dark)
    const holeMat = new THREE.MeshStandardMaterial({ color: 0x050508 });

    for (let gz = 0; gz < rows; gz++) {
      for (let gx = 0; gx < cols; gx++) {
        const key = `${gx},${gz}`;
        const wp = this.gridToWorld(gx, gz);
        if (this.holeSet.has(key)) {
          // Hole: add a subtle dark border ring
          const ringGeo = new THREE.RingGeometry(CELL*0.35, CELL*0.48, 12);
          const ring = new THREE.Mesh(ringGeo, new THREE.MeshStandardMaterial({
            color: 0x1a0505, transparent:true, opacity:0.7, side: THREE.DoubleSide
          }));
          ring.rotation.x = -Math.PI/2;
          ring.position.set(wp.x, 0.001, wp.z);
          this.boardGroup.add(ring);
        } else {
          // Solid floor tile (slightly inset from neighbors)
          const geo = new THREE.BoxGeometry(CELL - 0.02, BOARD_T, CELL - 0.02);
          const tile = new THREE.Mesh(geo, floorMat);
          tile.position.set(wp.x, -BOARD_T/2, wp.z);
          tile.receiveShadow = true;
          this.boardGroup.add(tile);
        }
      }
    }

    // Board surround (thick outer frame)
    const boardW = lvl.cols * CELL;
    const boardD = lvl.rows * CELL;
    const edgeMat = new THREE.MeshStandardMaterial({
      color: 0x5c3010,
      roughness: 0.8, metalness: 0.0
    });
    // Bottom plate (under holes)
    const underGeo = new THREE.BoxGeometry(boardW + 0.4, BOARD_T * 0.5, boardD + 0.4);
    const under = new THREE.Mesh(underGeo, edgeMat);
    under.position.set(0, -BOARD_T * 1.2, 0);
    under.receiveShadow = true;
    this.boardGroup.add(under);
  }

  buildWalls(lvl) {
    const cols = lvl.cols, rows = lvl.rows;
    const boardW = cols * CELL;
    const boardH = rows * CELL;
    const wallMat = new THREE.MeshStandardMaterial({
      color: 0x5c3010, roughness: 0.65, metalness: 0.05
    });

    const addWall = (x, y, z, sx, sy, sz) => {
      const geo = new THREE.BoxGeometry(sx, sy, sz);
      const mesh = new THREE.Mesh(geo, wallMat);
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      this.boardGroup.add(mesh);
      // Store AABB for collision
      this.wallAABBs.push({
        minX: x - sx/2, maxX: x + sx/2,
        minZ: z - sz/2, maxZ: z + sz/2
      });
    };

    const wy = WALL_H/2; // wall center Y

    // ── Outer border walls ─────────────────────────────────────────
    const ox = -boardW/2, oz = -boardH/2;
    const wt = WALL_T, wh = WALL_H;
    // North (z-)
    addWall(0, wy, oz - wt/2, boardW + wt*2, wh, wt);
    // South (z+)
    addWall(0, wy, oz + boardH + wt/2, boardW + wt*2, wh, wt);
    // West (x-)
    addWall(ox - wt/2, wy, 0, wt, wh, boardH);
    // East (x+)
    addWall(ox + boardW + wt/2, wy, 0, wt, wh, boardH);

    // ── Interior walls from level definition ───────────────────────
    (lvl.walls || []).forEach(w => {
      const gx = w.x, gz = w.z, face = w.face;
      // 'e' = east face of cell (x+ side)
      // 's' = south face of cell (z+ side)
      if (face === 'e') {
        const wx = (gx + 1) * CELL - boardW/2;
        const wz = (gz + 0.5) * CELL - boardH/2;
        addWall(wx, wy, wz, WALL_T, WALL_H, CELL);
      } else if (face === 's') {
        const wx = (gx + 0.5) * CELL - boardW/2;
        const wz = (gz + 1) * CELL - boardH/2;
        addWall(wx, wy, wz, CELL, WALL_H, WALL_T);
      }
    });
  }

  buildGems(lvl) {
    const gemMat = new THREE.MeshStandardMaterial({
      color: 0x00e5ff,
      emissive: 0x00b8d4,
      emissiveIntensity: 0.8,
      roughness: 0.1,
      metalness: 0.3,
      transparent: true,
      opacity: 0.92
    });
    (lvl.gems || []).forEach((g, i) => {
      const wp = this.gridToWorld(g[0], g[1]);
      const geo = new THREE.OctahedronGeometry(0.22, 0);
      const mesh = new THREE.Mesh(geo, gemMat.clone());
      mesh.position.set(wp.x, 0.38, wp.z);
      mesh.castShadow = true;
      mesh.userData = { baseY: 0.38, phase: Math.random() * Math.PI * 2, idx: i };
      this.boardGroup.add(mesh);
      this.gems3D.push({ mesh, gx: g[0], gz: g[1], collected: false });

      // Gem glow
      const glow = new THREE.PointLight(0x00e5ff, 0.6, 2.5);
      glow.position.set(wp.x, 0.6, wp.z);
      this.boardGroup.add(glow);
    });
  }

  buildGoal(lvl) {
    const gp = this.gridToWorld(lvl.goal[0], lvl.goal[1]);
    // Goal ring
    const ringGeo = new THREE.TorusGeometry(0.35, 0.06, 12, 32);
    const ringMat = new THREE.MeshStandardMaterial({
      color: 0x00ff88,
      emissive: 0x00cc66,
      emissiveIntensity: 1.0,
      roughness: 0.2, metalness: 0.5
    });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = Math.PI/2;
    ring.position.set(gp.x, 0.04, gp.z);
    this.boardGroup.add(ring);

    // Goal disc
    const discGeo = new THREE.CircleGeometry(0.32, 32);
    const discMat = new THREE.MeshStandardMaterial({
      color: 0x00cc66,
      emissive: 0x00aa55,
      emissiveIntensity: 0.7,
      transparent: true, opacity: 0.7,
      side: THREE.DoubleSide
    });
    const disc = new THREE.Mesh(discGeo, discMat);
    disc.rotation.x = -Math.PI/2;
    disc.position.set(gp.x, 0.03, gp.z);
    this.boardGroup.add(disc);

    // Goal light
    const gLight = new THREE.PointLight(0x00ff88, 1.0, 4);
    gLight.position.set(gp.x, 1, gp.z);
    this.boardGroup.add(gLight);

    this.goal3D = { ring, disc, gLight, gx: lvl.goal[0], gz: lvl.goal[1], x: gp.x, z: gp.z };
  }

  buildBall(lvl) {
    const sp = this.gridToWorld(lvl.start[0], lvl.start[1]);
    const geo = new THREE.SphereGeometry(BALL_R, 32, 32);
    const mat = new THREE.MeshStandardMaterial({
      color: 0xe8e8f0,
      roughness: 0.15,
      metalness: 0.95,
      envMapIntensity: 1.0
    });
    this.ball = new THREE.Mesh(geo, mat);
    this.ball.castShadow = true;
    this.ball.receiveShadow = false;
    this.ball.position.set(sp.x, BALL_R, sp.z);
    this.boardGroup.add(this.ball);

    this.ballX = sp.x;
    this.ballZ = sp.z;
  }

  // ── PROCEDURAL WOOD TEXTURE ──────────────────────────────────────────
  createWoodTexture(w, h, c1, c2) {
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext('2d');

    // Base color
    ctx.fillStyle = c1;
    ctx.fillRect(0, 0, w, h);

    // Wood grain lines
    ctx.strokeStyle = c2;
    for (let i = 0; i < 60; i++) {
      const y = (i / 60) * h;
      const amp = 3 + Math.random() * 8;
      const freq = 0.01 + Math.random() * 0.02;
      ctx.beginPath();
      ctx.lineWidth = 0.5 + Math.random() * 1.5;
      ctx.globalAlpha = 0.25 + Math.random() * 0.3;
      for (let x = 0; x < w; x++) {
        const cy = y + Math.sin(x * freq + Math.random()*0.1) * amp;
        x === 0 ? ctx.moveTo(x, cy) : ctx.lineTo(x, cy);
      }
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Knots
    for (let k = 0; k < 3; k++) {
      const kx = Math.random() * w;
      const ky = Math.random() * h;
      const gr = ctx.createRadialGradient(kx,ky,1, kx,ky,20+Math.random()*30);
      gr.addColorStop(0, 'rgba(80,40,10,0.4)');
      gr.addColorStop(1, 'rgba(80,40,10,0)');
      ctx.fillStyle = gr;
      ctx.fillRect(0,0,w,h);
    }

    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(2, 2);
    return tex;
  }

  // ── LEVEL INTRO ──────────────────────────────────────────────────────
  showLevelIntro(idx, name) {
    const el = document.getElementById('level-intro');
    document.getElementById('intro-num').textContent = `Level ${idx+1}`;
    document.getElementById('intro-name').textContent = name;
    el.classList.add('show');
    setTimeout(() => {
      el.classList.remove('show');
      setTimeout(() => {
        this.gameState = 'playing';
        this.timerRunning = true;
        this.lastTime = performance.now();
      }, 500);
    }, 2200);
  }

  // ── PHYSICS UPDATE ───────────────────────────────────────────────────
  updatePhysics(dt) {
    if (this.ballFalling) {
      this.ballFallVelY += -18 * dt;
      this.ballFallY += this.ballFallVelY * dt;
      if (this.ball) {
        this.ball.position.y = BALL_R + this.ballFallY;
        // Also drift outward
        this.ball.position.x += this.ballVelX * dt * 0.3;
        this.ball.position.z += this.ballVelZ * dt * 0.3;
      }
      return;
    }

    // Gravity component on tilted board
    const GRAVITY = 9.8;
    const FRICTION = 0.82; // damping per second (exponential)
    const MAX_SPEED = 7.0;
    const TILT_SPEED = 2.0; // rad/s for tilt response
    const MAX_TILT = 0.22;  // ~12.6 degrees

    // Tilt input
    let tx = 0, tz = 0;
    if (this.keys['ArrowUp']    || this.keys['KeyW']) tx -= 1;
    if (this.keys['ArrowDown']  || this.keys['KeyS']) tx += 1;
    if (this.keys['ArrowLeft']  || this.keys['KeyA']) tz += 1;
    if (this.keys['ArrowRight'] || this.keys['KeyD']) tz -= 1;

    this.targetTiltX = tx * MAX_TILT;
    this.targetTiltZ = tz * MAX_TILT;

    // Smooth tilt (ease in/out)
    const tiltSmooth = 1 - Math.pow(0.01, dt * TILT_SPEED * 2);
    this.tiltX += (this.targetTiltX - this.tiltX) * tiltSmooth;
    this.tiltZ += (this.targetTiltZ - this.tiltZ) * tiltSmooth;

    // Apply tilt to board group
    this.boardGroup.rotation.x = this.tiltX;
    this.boardGroup.rotation.z = this.tiltZ;

    // Acceleration due to gravity on tilted surface
    // ax = g * sin(tiltX) along Z, az = g * sin(tiltZ) along X
    const ax =  GRAVITY * Math.sin(this.tiltX);
    const az = -GRAVITY * Math.sin(this.tiltZ);

    this.ballVelX += az * dt;
    this.ballVelZ += ax * dt;

    // Friction (exponential decay)
    const frictionFactor = Math.pow(FRICTION, dt * 60);
    this.ballVelX *= frictionFactor;
    this.ballVelZ *= frictionFactor;

    // Clamp speed
    const speed = Math.sqrt(this.ballVelX**2 + this.ballVelZ**2);
    if (speed > MAX_SPEED) {
      this.ballVelX = (this.ballVelX/speed) * MAX_SPEED;
      this.ballVelZ = (this.ballVelZ/speed) * MAX_SPEED;
    }

    // Move ball
    let nx = this.ballX + this.ballVelX * dt;
    let nz = this.ballZ + this.ballVelZ * dt;

    // Wall collision
    [nx, nz] = this.resolveWallCollisions(nx, nz);

    this.ballX = nx;
    this.ballZ = nz;

    // Rolling rotation
    if (this.ball) {
      const dist = Math.sqrt(this.ballVelX**2 + this.ballVelZ**2) * dt;
      const rollAngle = dist / BALL_R;
      // Rotate around perpendicular to velocity
      const velLen = Math.sqrt(this.ballVelX**2 + this.ballVelZ**2);
      if (velLen > 0.01) {
        const axis = new THREE.Vector3(-this.ballVelZ/velLen, 0, this.ballVelX/velLen);
        this.ball.rotateOnWorldAxis(axis, rollAngle);
      }
      this.ball.position.x = this.ballX;
      this.ball.position.z = this.ballZ;
      this.ball.position.y = BALL_R;
    }

    // ── Check board bounds (edges) ───────────────────────────────────
    const hw = this.boardW/2, hh = this.boardH_world/2;
    const edgeMargin = BALL_R * 0.5;
    if (Math.abs(this.ballX) > hw - edgeMargin || Math.abs(this.ballZ) > hh - edgeMargin) {
      this.triggerFall('edge');
      return;
    }

    // ── Check holes ───────────────────────────────────────────────────
    const gx = Math.floor((this.ballX + hw) / CELL);
    const gz = Math.floor((this.ballZ + hh) / CELL);
    if (this.holeSet.has(`${gx},${gz}`)) {
      this.triggerFall('hole');
      return;
    }

    // ── Check gem collection ──────────────────────────────────────────
    this.gems3D.forEach((g, i) => {
      if (g.collected) return;
      const dx = this.ballX - g.mesh.position.x;
      const dz = this.ballZ - g.mesh.position.z;
      const dist = Math.sqrt(dx*dx + dz*dz);
      if (dist < BALL_R + 0.28) {
        this.collectGem(i);
      }
    });

    // ── Check goal ────────────────────────────────────────────────────
    if (this.goal3D && this.gemsCollected >= this.totalGems) {
      const dx = this.ballX - this.goal3D.x;
      const dz = this.ballZ - this.goal3D.z;
      const dist = Math.sqrt(dx*dx + dz*dz);
      if (dist < 0.38) {
        this.triggerComplete();
      }
    }
  }

  resolveWallCollisions(nx, nz) {
    const r = BALL_R;
    for (const w of this.wallAABBs) {
      // Expand AABB by ball radius
      const minX = w.minX - r, maxX = w.maxX + r;
      const minZ = w.minZ - r, maxZ = w.maxZ + r;
      if (nx > minX && nx < maxX && nz > minZ && nz < maxZ) {
        // Find shallowest penetration axis
        const dLeft  = nx - minX;
        const dRight = maxX - nx;
        const dTop   = nz - minZ;
        const dBot   = maxZ - nz;
        const minD   = Math.min(dLeft, dRight, dTop, dBot);
        const BOUNCE = 0.22;
        if (minD === dLeft)  { nx = minX; this.ballVelX = Math.abs(this.ballVelX) * BOUNCE; }
        else if (minD === dRight) { nx = maxX; this.ballVelX = -Math.abs(this.ballVelX) * BOUNCE; }
        else if (minD === dTop)   { nz = minZ; this.ballVelZ = Math.abs(this.ballVelZ) * BOUNCE; }
        else                      { nz = maxZ; this.ballVelZ = -Math.abs(this.ballVelZ) * BOUNCE; }
      }
    }
    return [nx, nz];
  }

  // ── GAME EVENTS ──────────────────────────────────────────────────────
  collectGem(i) {
    const g = this.gems3D[i];
    if (g.collected) return;
    g.collected = true;
    this.gemsCollected++;

    // Particle burst
    this.spawnGemParticles(g.mesh.position.clone());

    // Remove gem
    this.boardGroup.remove(g.mesh);

    // Flash
    const flash = document.getElementById('gem-flash');
    flash.style.opacity = '1';
    setTimeout(() => { flash.style.opacity = '0'; }, 120);

    this.updateHUD();
  }

  spawnGemParticles(pos) {
    const count = 18;
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i*3]   = pos.x;
      positions[i*3+1] = pos.y;
      positions[i*3+2] = pos.z;
      const angle = (i / count) * Math.PI * 2;
      const speed = 1.5 + Math.random() * 2;
      velocities.push({
        x: Math.cos(angle) * speed,
        y: 2 + Math.random() * 2,
        z: Math.sin(angle) * speed
      });
    }
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0x00e5ff, size: 0.12, transparent: true, opacity: 1.0
    });
    const points = new THREE.Points(geo, mat);
    this.boardGroup.add(points);
    this.particleSystems.push({
      points, geo, mat, velocities,
      positions: positions,
      life: 1.0
    });
  }

  updateParticles(dt) {
    const GRAVITY = 4;
    for (let i = this.particleSystems.length - 1; i >= 0; i--) {
      const ps = this.particleSystems[i];
      ps.life -= dt * 1.5;
      if (ps.life <= 0) {
        this.boardGroup.remove(ps.points);
        this.particleSystems.splice(i, 1);
        continue;
      }
      const pos = ps.positions;
      ps.velocities.forEach((v, j) => {
        v.y -= GRAVITY * dt;
        pos[j*3]   += v.x * dt;
        pos[j*3+1] += v.y * dt;
        pos[j*3+2] += v.z * dt;
      });
      ps.geo.attributes.position.needsUpdate = true;
      ps.mat.opacity = Math.max(0, ps.life);
    }
  }

  triggerFall(reason) {
    if (this.gameState !== 'playing') return;
    this.gameState = 'dead';
    this.timerRunning = false;
    this.ballFalling = true;
    this.ballFallY = 0;
    this.ballFallVelY = 0;

    setTimeout(() => {
      document.getElementById('gameover-time').textContent = this.formatTime(this.elapsedTime);
      document.getElementById('gameover-gems').textContent = `${this.gemsCollected} / ${this.totalGems}`;
      document.getElementById('gameover-subtitle').textContent =
        reason === 'hole' ? 'The ball slipped into the void...' : 'The ball rolled off the edge...';
      document.getElementById('overlay-gameover').classList.add('visible');
    }, 800);
  }

  triggerComplete() {
    if (this.gameState !== 'playing') return;
    this.gameState = 'complete';
    this.timerRunning = false;

    // Ball falls into goal
    this.ballFalling = true;
    this.ballFallY = 0;
    this.ballFallVelY = 0;
    this.ballVelX = 0; this.ballVelZ = 0;

    setTimeout(() => {
      document.getElementById('complete-time').textContent = this.formatTime(this.elapsedTime);
      document.getElementById('complete-gems').textContent = `${this.gemsCollected} / ${this.totalGems}`;

      const subs = [
        "The ball finds its way.",
        "Precision and patience.",
        "A perfect run!",
        "Masterful control.",
        "The maze yields to you."
      ];
      document.getElementById('complete-subtitle').textContent = subs[this.currentLevel % subs.length];

      const btnNext = document.getElementById('btn-next-level');
      if (this.currentLevel >= LEVELS.length - 1) {
        btnNext.textContent = '🎉 You Beat All Levels!';
        btnNext.onclick = () => this.loadLevel(0);
      } else {
        btnNext.textContent = 'Next Level →';
        btnNext.onclick = () => this.nextLevel();
      }

      document.getElementById('overlay-complete').classList.add('visible');
    }, 600);
  }

  nextLevel() {
    document.getElementById('overlay-complete').classList.remove('visible');
    const next = Math.min(this.currentLevel + 1, LEVELS.length - 1);
    setTimeout(() => this.loadLevel(next), 300);
  }

  restartLevel() {
    document.getElementById('overlay-complete').classList.remove('visible');
    document.getElementById('overlay-gameover').classList.remove('visible');
    setTimeout(() => this.loadLevel(this.currentLevel), 200);
  }

  // ── HUD UPDATE ───────────────────────────────────────────────────────
  updateHUD() {
    document.getElementById('hud-gems-val').textContent = `${this.gemsCollected} / ${this.totalGems}`;
    document.getElementById('hud-timer-val').textContent = this.formatTime(this.elapsedTime);
  }

  formatTime(t) {
    const s = Math.floor(t);
    const ms = Math.floor((t - s) * 10);
    return `${s}.${ms}`;
  }

  // ── GEM & GOAL ANIMATION ─────────────────────────────────────────────
  animateGems(t) {
    this.gems3D.forEach(g => {
      if (g.collected) return;
      const phase = g.mesh.userData.phase;
      g.mesh.position.y = g.mesh.userData.baseY + Math.sin(t * 2 + phase) * 0.06;
      g.mesh.rotation.y += 0.016;
    });

    // Goal pulse
    if (this.goal3D) {
      const ready = this.gemsCollected >= this.totalGems;
      const pulse = 0.7 + Math.sin(t * 4) * (ready ? 0.5 : 0.2);
      this.goal3D.gLight.intensity = ready ? pulse * 1.5 : pulse * 0.5;
      this.goal3D.ring.material.emissiveIntensity = ready ? pulse : 0.5;
    }
  }

  // ── MAIN LOOP ────────────────────────────────────────────────────────
  animate(now) {
    requestAnimationFrame(t => this.animate(t));
    const dt = Math.min((now - this.lastTime) / 1000, 0.05);
    this.lastTime = now;

    if (this.gameState === 'playing') {
      if (this.timerRunning) this.elapsedTime += dt;
      this.updatePhysics(dt);
      this.updateParticles(dt);
      this.animateGems(now / 1000);
      this.updateHUD();

      // Move ball light
      if (this.ball && this.ballLight) {
        const bwp = this.ball.getWorldPosition(new THREE.Vector3());
        this.ballLight.position.copy(bwp).add(new THREE.Vector3(0, 1, 0));
      }
    } else if (this.gameState === 'dead' && this.ballFalling) {
      const fallDt = Math.min(dt, 0.05);
      this.ballFallVelY -= 18 * fallDt;
      this.ballFallY += this.ballFallVelY * fallDt;
      if (this.ball) {
        this.ball.position.y = BALL_R + this.ballFallY;
      }
      this.animateGems(now / 1000);
    } else if (this.gameState === 'complete' && this.ballFalling) {
      const fallDt = Math.min(dt, 0.05);
      this.ballFallVelY -= 12 * fallDt;
      this.ballFallY += this.ballFallVelY * fallDt;
      if (this.ball) {
        this.ball.position.y = BALL_R + this.ballFallY;
        // Shrink into goal
        const s = Math.max(0, 1 + this.ballFallY * 1.5);
        this.ball.scale.setScalar(s);
      }
      this.animateGems(now / 1000);
    } else if (this.gameState === 'intro') {
      this.animateGems(now / 1000);
    }

    // Camera subtle follow
    const camTiltX = this.tiltX * 0.4;
    const camTiltZ = this.tiltZ * 0.4;
    this.camera.position.x = Math.sin(camTiltZ) * 3;
    this.camera.position.y = this.cameraBasePos.y + Math.sin(camTiltX) * 2;
    this.camera.position.z = this.cameraBasePos.z;
    this.camera.lookAt(0, 0, 0);

    this.renderer.render(this.scene, this.camera);
  }
}

// ── BOOT ───────────────────────────────────────────────────────────────
window.addEventListener('load', () => {
  new BallRollMaze();
});
</script>
</body>
</html>
