<script>
'use strict';

// ─────────────────────────────────────────────
//  LEVEL DEFINITIONS
// ─────────────────────────────────────────────
// Grid: board is W x H cells, each cell = CELL_SIZE units
// Walls: [x, z, 'h'|'v'] — h = horizontal wall on south face of cell, v = vertical wall on east face
// Holes: [x, z] — missing floor tile
// Gems: [x, z]
// Start: [x, z] — ball start
// Goal: [x, z]

const CELL = 1.8;   // cell size in world units
const WALL_H = 0.55; // wall height
const WALL_T = 0.14; // wall thickness
const BALL_R = 0.22; // ball radius
const BOARD_T = 0.22; // board thickness

const LEVELS = [
  // ── Level 1: The First Roll ──────────────────────────────────────────
  {
    name: "The First Roll",
    cols: 7, rows: 7,
    start: [1, 1],
    goal:  [5, 5],
    gems:  [[3, 1], [5, 3]],
    holes: [],
    walls: [
      // outer walls are auto-generated
      // interior corridors
      {x:2,z:0,face:'s'}, {x:3,z:0,face:'s'},
