#intro {
  position:fixed; top:50%; left:50%;
  transform:translate(-50%,-50%);
  text-align:center; pointer-events:none; z-index:50;
  opacity:0; transition:opacity .4s;
}
#intro.on { opacity:1; }
#intro-num  { font-size:11px; letter-spacing:.2em; text-transform:uppercase; color:rgba(255,255,255,.4); margin-bottom:4px; }
#intro-name { font-size:34px; font-weight:900; }

/* ── GEM FLASH ── */
#gflash {
  position:fixed; top:0; left:0; right:0; bottom:0;
  pointer-events:none; z-index:5;
  background:radial-gradient(circle at 50% 50%, rgba(0,229,255,.18) 0%, transparent 60%);
  opacity:0; transition:opacity .08s;
}

/* ── HINT ── */
#hint {
  position:fixed; bottom:18px; left:50%;
  transform:translateX(-50%);
  font-size:11px; letter-spacing:.09em;
  color:rgba(255,255,255,.28); pointer-events:none; z-index:10;
}

/* ── GEMS LEFT INDICATOR ── */
#gems-left-msg {
  position:fixed; bottom:50px; left:50%;
  transform:translateX(-50%);
  font-size:13px; color:#00e5ff;
  opacity:0; transition:opacity .3s;
  pointer-events:none; z-index:10;
}
</style>
</head>
<body>
<canvas id="c"></canvas>

<!-- HUD -->
<div id="hud">
  <div class="hcard"><div class="hlabel">Level</div><div class="hval" id="hv-level">1</div></div>
  <div class="hcard"><div class="hlabel">Gems</div><div class="hval" id="hv-gems">0/0</div></div>
  <div class="hcard"><div class="hlabel">Time</div><div class="hval" id="hv-timer">0.0</div></div>
  <div class="hcard"><button id="btn-restart">↺ Restart</button></div>
</div>

<!-- Level Intro -->
<div id="intro"><div id="intro-num">Level 1</div><div id="intro-name">The First Roll</div></div>

<!-- Gem flash -->
<div id="gflash"></div>

<!-- Gems left hint -->
<div id="gems-left-msg">Collect all gems to open the goal!</div>

<!-- Level Complete -->
<div class="overlay" id="ov-win">
  <div class="ocard">
    <div class="otitle" style="color:#00e5ff">✦ Level Complete!</div>
    <div class="osub" id="ov-win-sub">Well done!</div>
    <div class="ostat"><span class="ostat-l">Time</span><span class="ostat-v" style="color:#ffd54f" id="ov-win-time">—</span></div>
    <div class="ostat"><span class="ostat-l">Gems</span><span class="ostat-v" style="color:#00e5ff" id="ov-win-gems">—</span></div>
    <button class="btn btn-blue" id="btn-next">Next Level →</button><br>
    <button class="btn btn-ghost" id="btn-replay-win">Replay Level</button>
  </div>
</div>

<!-- Game Over -->
<div class="overlay" id="ov-dead">
  <div class="ocard">
    <div class="otitle" style="color:#ff5252">✕ Ball Lost!</div>
    <div class="osub" id="ov-dead-sub">The ball slipped into the void...</div>
    <div class="ostat"><span class="ostat-l">Survived</span><span class="ostat-v" style="color:#ffd54f" id="ov-dead-time">—</span></div>
    <div class="ostat"><span class="ostat-l">Gems</span><span class="ostat-v" style="color:#00e5ff" id="ov-dead-gems">—</span></div>
    <button class="btn btn-red" id="btn-retry">↺ Try Again</button>
  </div>
</div>

<div id="hint">WASD / Arrow Keys — Tilt the Board &nbsp;|&nbsp; R — Restart Level</div>

