#c { display:block; position:fixed; top:0; left:0; }

/* ── HUD ── */
#hud {
  position:fixed; top:0; left:0; right:0;
  padding:14px 20px;
  display:flex; justify-content:space-between; align-items:center;
  pointer-events:none; z-index:20;
}
.hcard {
  background:rgba(0,0,0,0.6);
  backdrop-filter:blur(10px);
  border:1px solid rgba(255,255,255,0.1);
  border-radius:12px;
  padding:8px 16px;
  min-width:80px; text-align:center;
  pointer-events:auto;
}
.hlabel {
  font-size:9px; letter-spacing:.15em;
  text-transform:uppercase; color:rgba(255,255,255,.45);
  margin-bottom:2px;
}
.hval { font-size:20px; font-weight:800; line-height:1; }
#hv-level { color:#fff; }
#hv-gems  { color:#00e5ff; }
#hv-timer { color:#ffd54f; }
#btn-restart {
  background:rgba(255,255,255,.08);
  border:1px solid rgba(255,255,255,.18);
  border-radius:9px; padding:7px 15px;
  font-size:12px; color:rgba(255,255,255,.65);
  cursor:pointer; transition:all .2s;
  pointer-events:auto;
  font-family:inherit;
}
#btn-restart:hover { background:rgba(255,255,255,.16); color:#fff; }

/* ── OVERLAYS ── */
.overlay {
  position:fixed; inset:0;
  display:flex; align-items:center; justify-content:center;
  z-index:100; background:rgba(0,0,0,.65);
  backdrop-filter:blur(6px);
  opacity:0; pointer-events:none;
  transition:opacity .35s ease;
}
.overlay.on { opacity:1; pointer-events:auto; }
.ocard {
  background:rgba(10,10,18,.97);
  border:1px solid rgba(255,255,255,.12);
  border-radius:22px; padding:42px 52px;
  text-align:center; max-width:400px; width:90%;
  box-shadow:0 24px 80px rgba(0,0,0,.9);
}
.otitle { font-size:30px; font-weight:800; margin-bottom:6px; }
.osub   { font-size:13px; color:rgba(255,255,255,.45); margin-bottom:26px; line-height:1.5; }
.ostat  {
  display:flex; justify-content:space-between; align-items:center;
  padding:9px 0; border-bottom:1px solid rgba(255,255,255,.06);
}
.ostat:last-of-type { margin-bottom:20px; }
.ostat-l { font-size:12px; color:rgba(255,255,255,.45); }
.ostat-v { font-size:17px; font-weight:700; }
.btn {
  display:inline-block; padding:13px 34px;
  border-radius:11px; font-size:15px; font-weight:700;
  cursor:pointer; border:none; font-family:inherit;
  transition:transform .15s, box-shadow .15s;
  letter-spacing:.02em;
}
.btn:hover { transform:translateY(-2px); }
.btn-blue  { background:linear-gradient(135deg,#00e5ff,#0088cc); color:#000; }
.btn-blue:hover  { box-shadow:0 8px 28px rgba(0,200,255,.4); }
.btn-red   { background:linear-gradient(135deg,#ff5252,#c62828); color:#fff; }
.btn-red:hover   { box-shadow:0 8px 28px rgba(255,80,80,.4); }
.btn-ghost {
  background:rgba(255,255,255,.08);
  border:1px solid rgba(255,255,255,.18); color:#fff;
  margin-top:10px;
}
.btn-ghost:hover { background:rgba(255,255,255,.16); }

/* ── INTRO FLASH ── */
#intro {
  position:fixed; top:50%; left:50%;
  transform:translate(-50%,-50%);
  text-align:center; pointer-events:none; z-index:50;
  opacity:0; transition:opacity .4s;
}
#intro.on { opacity:1; }
#intro-num  { font-size:11px; letter-spacing:.2em; text-transform:uppercase; color:rgba(255,255,255,.4); margin-bottom:4px; }
#intro-name { font-size:34px; font-weight:900; }

/* ── GEM FLASH ── */
#gflash {
  position:fixed; top:0; left:0; right:0; bottom:0;
  pointer-events:none; z-index:5;
  background:radial-gradient(circle at 50% 50%, rgba(0,229,255,.18) 0%, transparent 60%);
  opacity:0; transition:opacity .08s;
}

/* ── HINT ── */
#hint {
  position:fixed; bottom:18px; left:50%;
  transform:translateX(-50%);
  font-size:11px; letter-spacing:.09em;
  color:rgba(255,255,255,.28); pointer-events:none; z-index:10;
}

/* ── GEMS LEFT INDICATOR ── */
#gems-left-msg {
  position:fixed; bottom:50px; left:50%;
  transform:translateX(-50%);
  font-size:13px; color:#00e5ff;
  opacity:0; transition:opacity .3s;
  pointer-events:none; z-index:10;
}
</style>
</head>
