      {x:10,z:3,face:'s'},{x:10,z:4,face:'e'},{x:10,z:4,face:'s'},
      {x:12,z:2,face:'s'},{x:12,z:5,face:'s'},
      {x:7,z:3,face:'e'},{x:7,z:4,face:'e'},
    ]
  },

  // ─────────── LEVEL 8: The Void ──────────────────────────────
  {
    name:'The Void', cols:12, rows:12,
    start:[1,1], goal:[10,10],
    gems:[[5,1],[10,1],[1,5],[10,5],[1,10],[5,10],[5,5],[7,7]],
    holes:[
      // Large void sections — only narrow paths
      [2,2],[3,2],[4,2],[5,2],[6,2],[7,2],[8,2],[9,2],
      [2,3],[9,3],
      [2,4],[3,4],[4,4],[5,4],[6,4],[7,4],[8,4],[9,4],
      [4,5],[5,5],[6,5],[7,5],
      [4,6],[5,6],[6,6],[7,6],
      [2,7],[3,7],[4,7],[7,7],[8,7],[9,7],
      [2,8],[9,8],
      [2,9],[3,9],[4,9],[5,9],[6,9],[7,9],[8,9],[9,9],
    ],
    walls:[
      // Guide rails for outer corridor
      {x:1,z:2,face:'s'},{x:1,z:9,face:'s'},
      {x:10,z:2,face:'s'},{x:10,z:9,face:'s'},
      {x:0,z:3,face:'e'},{x:0,z:8,face:'e'},
      {x:10,z:3,face:'e'},{x:10,z:8,face:'e'},
      // Inner paths
      {x:3,z:3,face:'s'},{x:4,z:3,face:'s'},{x:5,z:3,face:'s'},
      {x:6,z:3,face:'s'},{x:7,z:3,face:'s'},{x:8,z:3,face:'s'},
      {x:3,z:8,face:'s'},{x:4,z:8,face:'s'},{x:5,z:8,face:'s'},
      {x:6,z:8,face:'s'},{x:7,z:8,face:'s'},{x:8,z:8,face:'s'},
      {x:3,z:4,face:'e'},{x:3,z:5,face:'e'},{x:3,z:6,face:'e'},{x:3,z:7,face:'e'},
      {x:8,z:4,face:'e'},{x:8,z:5,face:'e'},{x:8,z:6,face:'e'},{x:8,z:7,face:'e'},
      {x:5,z:6,face:'e'},{x:6,z:5,face:'s'},{x:6,z:6,face:'s'},{x:5,z:5,face:'s'},
    ]
  },

];

// ═══════════════════════════════════════════════════════════════
//  UTILITIES
// ═══════════════════════════════════════════════════════════════
function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function formatTime(t) {
  const s = Math.floor(t), ms = Math.floor((t - s) * 10);
  return `${s}.${ms}`;
}

// ═══════════════════════════════════════════════════════════════
//  GAME
// ═══════════════════════════════════════════════════════════════
class Game {
  constructor() {
    this.lvlIdx    = 0;
    this.state     = 'intro';   // intro | playing | dead | win
    this.elapsed   = 0;
    this.tiltX     = 0;   // board rotation around X (pitch — forward/back)
    this.tiltZ     = 0;   // board rotation around Z (roll — left/right)
    this.tTiltX    = 0;   // target tilt
    this.tTiltZ    = 0;
    this.bx        = 0;   // ball position in board-local coords
    this.bz        = 0;
    this.bvx       = 0;   // ball velocity
    this.bvz       = 0;
    this.falling   = false;
    this.fallVY    = 0;
    this.fallY     = 0;
    this.gemsGot   = 0;
    this.gemsTotal = 0;
    this.gemObjs   = [];  // {mesh, wx, wz, collected}
    this.wallBoxes = [];  // {minX,maxX,minZ,maxZ}
    this.holeKeys  = new Set();
    this.particles = [];
    this.keys      = {};
    this.prevT     = 0;
    this.boardW    = 0;
    this.boardD    = 0;

    this._buildRenderer();
    this._buildScene();
    this._buildLighting();
    this._bindInput();
    this._hookUI();
    this.loadLevel(0);
    requestAnimationFrame(t => this._loop(t));
  }

  // ── Renderer ───────────────────────────────────────────────
  _buildRenderer() {
    const cvs = document.getElementById('c');
    this.renderer = new THREE.WebGLRenderer({canvas:cvs, antialias:true});
    this.renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    this.renderer.setSize(innerWidth, innerHeight);
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.outputEncoding = THREE.sRGBEncoding;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    addEventListener('resize', () => {
      this.camera.aspect = innerWidth / innerHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(innerWidth, innerHeight);
    });
  }

  // ── Scene & Camera ─────────────────────────────────────────
  _buildScene() {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x06060e);
    this.scene.fog = new THREE.FogExp2(0x06060e, 0.022);

    this.camera = new THREE.PerspectiveCamera(44, innerWidth/innerHeight, 0.1, 200);
    this.camera.position.set(0, 20, 16);
    this.camera.lookAt(0, 0, 0);
    this.camBase = this.camera.position.clone();

    this.boardGrp = new THREE.Group();
    this.scene.add(this.boardGrp);

    // Stars
    const sg = new THREE.BufferGeometry();
    const sp = new Float32Array(1200*3);
    for(let i=0;i<sp.length;i++) sp[i]=(Math.random()-.5)*150;
    sg.setAttribute('position', new THREE.BufferAttribute(sp,3));
    this.scene.add(new THREE.Points(sg,
      new THREE.PointsMaterial({color:0xffffff, size:0.18, transparent:true, opacity:0.55})));
  }

  // ── Lighting ───────────────────────────────────────────────
  _buildLighting() {
    this.scene.add(new THREE.AmbientLight(0x9aa8c0, 0.55));

    const sun = new THREE.DirectionalLight(0xfff8e8, 1.7);
    sun.position.set(10, 22, 10);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.near = 1; sun.shadow.camera.far = 70;
    sun.shadow.camera.left = sun.shadow.camera.bottom = -22;
    sun.shadow.camera.right = sun.shadow.camera.top = 22;
    sun.shadow.bias = -0.0008;
    this.scene.add(sun); this.sun = sun;

    const fill = new THREE.DirectionalLight(0x4466ff, 0.28);
    fill.position.set(-8,-5,-10); this.scene.add(fill);

    this.ballPt = new THREE.PointLight(0xffffff, 0.35, 5);
    this.scene.add(this.ballPt);
  }

  // ── Input ──────────────────────────────────────────────────
  _bindInput() {
    addEventListener('keydown', e => {
      this.keys[e.code] = true;
      if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)) e.preventDefault();
      if(e.code==='KeyR') this.restartLevel();
    });
    addEventListener('keyup', e => { this.keys[e.code] = false; });
  }

  _hookUI() {
    document.getElementById('btn-restart').onclick = () => this.restartLevel();
    document.getElementById('btn-next').onclick    = () => this.nextLevel();
    document.getElementById('btn-retry').onclick   = () => this.restartLevel();
    document.getElementById('btn-replay-win').onclick = () => this.restartLevel();
  }

  // ── Load Level ─────────────────────────────────────────────
  loadLevel(idx) {
    this.lvlIdx = idx;
    const L = LEVELS[idx];

    // Purge old scene objects
    while(this.boardGrp.children.length) {
      const c = this.boardGrp.children[0];
      this.boardGrp.remove(c);
      c.geometry?.dispose(); c.material?.dispose();
    }
    this.gemObjs   = [];
    this.wallBoxes = [];
    this.holeKeys  = new Set();
    this.particles = [];

    const cols = L.cols, rows = L.rows;
    this.boardW = cols * CELL;
    this.boardD = rows * CELL;

    // Helpers
    this.g2w = (gx, gz) => ({
      wx: (gx + .5)*CELL - this.boardW*.5,
      wz: (gz + .5)*CELL - this.boardD*.5
    });

    // Holes
    (L.holes||[]).forEach(([hx,hz]) => this.holeKeys.add(`${hx},${hz}`));

    // Build geometry
    this._buildBoard(L);
    this._buildWalls(L);
    this._buildGems(L);
    this._buildGoal(L);
    this._buildBall(L);

    // Reset physics
    this.tiltX=0; this.tiltZ=0; this.tTiltX=0; this.tTiltZ=0;
    this.boardGrp.rotation.set(0,0,0);
    this.bvx=0; this.bvz=0; this.falling=false;
    this.fallVY=0; this.fallY=0;
    this.gemsGot=0; this.gemsTotal=L.gems.length;
    this.gemColl = new Array(L.gems.length).fill(false);
    this.elapsed=0; this.state='intro';

    // UI
    document.getElementById('hv-level').textContent = idx+1;
    this._updateHUD();
    document.getElementById('ov-win').classList.remove('on');
    document.getElementById('ov-dead').classList.remove('on');

    // Adjust camera for board size
    const maxDim = Math.max(cols, rows);
    const dist = maxDim * CELL * 0.85;
    this.camBase.set(0, dist, dist * 0.8);
    this.camera.position.copy(this.camBase);
    this.camera.lookAt(0, 0, 0);

    this._showIntro(idx, L.name);
  }

  // ── Build Floor ────────────────────────────────────────────
  _buildBoard(L) {
    const cols = L.cols, rows = L.rows;
    const floorTex = this._woodTex(512, 512);
    const floorMat = new THREE.MeshStandardMaterial({
      map: floorTex, color:0xd4922c, roughness:.72, metalness:0
    });
    const darkMat = new THREE.MeshStandardMaterial({
      color:0x120608, roughness:.9, metalness:0
    });
    const edgeMat = new THREE.MeshStandardMaterial({
      color:0x5a2e0c, roughness:.8, metalness:.02
    });

    for(let gz=0;gz<rows;gz++) {
      for(let gx=0;gx<cols;gx++) {
        const {wx,wz} = this.g2w(gx,gz);
        if(!this.holeKeys.has(`${gx},${gz}`)) {
          const t = new THREE.Mesh(
            new THREE.BoxGeometry(CELL-.03, BD_T, CELL-.03), floorMat
          );
          t.position.set(wx, -BD_T*.5, wz);
          t.receiveShadow = true;
          this.boardGrp.add(t);
        } else {
          // Dark hole indicator (ring)
          const r = new THREE.Mesh(
            new THREE.RingGeometry(CELL*.3, CELL*.44, 16),
            new THREE.MeshBasicMaterial({color:0x1a0204, side:THREE.DoubleSide, transparent:true, opacity:.7})
          );
          r.rotation.x = -Math.PI*.5;
          r.position.set(wx, .002, wz);
          this.boardGrp.add(r);
          // Inner void
          const inner = new THREE.Mesh(
            new THREE.CircleGeometry(CELL*.28, 16),
            new THREE.MeshBasicMaterial({color:0x000000, side:THREE.DoubleSide})
          );
          inner.rotation.x = -Math.PI*.5;
          inner.position.set(wx, .001, wz);
          this.boardGrp.add(inner);
        }
      }
    }

    // Under-board plate
    const under = new THREE.Mesh(
      new THREE.BoxGeometry(this.boardW+.5, BD_T*.6, this.boardD+.5), edgeMat
    );
    under.position.set(0, -BD_T*1.3, 0);
    this.boardGrp.add(under);
  }

  // ── Build Walls ────────────────────────────────────────────
  _buildWalls(L) {
    const cols = L.cols, rows = L.rows;
    const bW = this.boardW, bD = this.boardD;
    const wMat = new THREE.MeshStandardMaterial({
      color:0x6b3810, roughness:.65, metalness:.04
    });
    const wy = WALL_H*.5;

    const add = (x,y,z,sx,sy,sz) => {
      const m = new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz), wMat);
      m.position.set(x,y,z);
      m.castShadow=true; m.receiveShadow=true;
      this.boardGrp.add(m);
      this.wallBoxes.push({minX:x-sx*.5,maxX:x+sx*.5,minZ:z-sz*.5,maxZ:z+sz*.5});
    };

    // Outer border
    add(0,wy,-bD*.5-WALL_T*.5, bW+WALL_T*2,WALL_H,WALL_T);
    add(0,wy, bD*.5+WALL_T*.5, bW+WALL_T*2,WALL_H,WALL_T);
    add(-bW*.5-WALL_T*.5,wy,0, WALL_T,WALL_H,bD);
    add( bW*.5+WALL_T*.5,wy,0, WALL_T,WALL_H,bD);

    // Interior walls
    (L.walls||[]).forEach(w => {
      const {face,x:gx,z:gz} = w;
      if(face==='e') {
        const wx = (gx+1)*CELL - bW*.5;
        const wz = (gz+.5)*CELL - bD*.5;
        add(wx, wy, wz, WALL_T, WALL_H, CELL+.01);
      } else if(face==='s') {
        const wx = (gx+.5)*CELL - bW*.5;
        const wz = (gz+1)*CELL - bD*.5;
        add(wx, wy, wz, CELL+.01, WALL_H, WALL_T);
      }
    });
  }

  // ── Build Gems ─────────────────────────────────────────────
  _buildGems(L) {
    const baseMat = new THREE.MeshStandardMaterial({
      color:0x00e5ff, emissive:0x00b0d4, emissiveIntensity:.85,
      roughness:.08, metalness:.25, transparent:true, opacity:.93
    });
    (L.gems||[]).forEach(([gx,gz], i) => {
      const {wx,wz} = this.g2w(gx,gz);
      const geo = new THREE.OctahedronGeometry(.23,0);
      const mat = baseMat.clone();
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(wx, .4, wz);
      mesh.castShadow = true;
      mesh.userData = {baseY:.4, phase:Math.random()*Math.PI*2};
      this.boardGrp.add(mesh);

      // Glow light
      const gl = new THREE.PointLight(0x00e5ff, .55, 2.8);
      gl.position.set(wx, .8, wz);
      this.boardGrp.add(gl);

      this.gemObjs.push({mesh, gl, wx, wz, collected:false});
    });
  }

  // ── Build Goal ─────────────────────────────────────────────
  _buildGoal(L) {
    const {wx,wz} = this.g2w(L.goal[0], L.goal[1]);

    const ringMat = new THREE.MeshStandardMaterial({
      color:0x00ff88, emissive:0x00cc55, emissiveIntensity:1.2,
      roughness:.2, metalness:.5
    });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(.38,.065,14,36), ringMat);
    ring.rotation.x = Math.PI*.5;
    ring.position.set(wx,.03,wz);
    this.boardGrp.add(ring);

    // Animated disc (rendered double-sided)
    const discMat = new THREE.MeshStandardMaterial({
      color:0x00cc55, emissive:0x00aa44, emissiveIntensity:.8,
      transparent:true, opacity:.65, side:THREE.DoubleSide
    });
    const disc = new THREE.Mesh(new THREE.CircleGeometry(.35,32), discMat);
    disc.rotation.x = -Math.PI*.5;
    disc.position.set(wx,.02,wz);
    this.boardGrp.add(disc);

    const gLight = new THREE.PointLight(0x00ff88, 1.1, 5);
    gLight.position.set(wx, 1.2, wz);
    this.boardGrp.add(gLight);

    this.goal = {ring, disc, gLight, wx, wz, gx:L.goal[0], gz:L.goal[1]};
  }

  // ── Build Ball ─────────────────────────────────────────────
  _buildBall(L) {
    const {wx,wz} = this.g2w(L.start[0], L.start[1]);
    const geo = new THREE.SphereGeometry(BALL_R, 40, 40);
    const mat = new THREE.MeshStandardMaterial({
      color:0xdde0ee, roughness:.12, metalness:.97, envMapIntensity:1.0
    });
    this.ball = new THREE.Mesh(geo, mat);
    this.ball.castShadow = true;
    this.ball.position.set(wx, BALL_R, wz);
    this.boardGrp.add(this.ball);
    this.bx = wx; this.bz = wz;
    this.ball.scale.setScalar(1);
  }

  // ── Wood Texture ───────────────────────────────────────────
  _woodTex(w, h) {
    const c = document.createElement('canvas');
    c.width=w; c.height=h;
    const ctx = c.getContext('2d');
    ctx.fillStyle='#c8881e';
    ctx.fillRect(0,0,w,h);
    const cols=['#a06010','#b87820','#c08020','#d09828','#bb7818'];
    for(let i=0;i<80;i++){
      const y=(i/80)*h;
      const amp=2+Math.random()*10;
      const freq=.008+Math.random()*.018;
      ctx.beginPath(); ctx.lineWidth=.4+Math.random()*2;
      ctx.strokeStyle=cols[i%cols.length];
      ctx.globalAlpha=.18+Math.random()*.28;
      for(let x=0;x<w;x++){
        const cy=y+Math.sin(x*freq+i*.3)*amp+Math.sin(x*.03)*3;
        x===0?ctx.moveTo(x,cy):ctx.lineTo(x,cy);
      }
      ctx.stroke();
    }
    ctx.globalAlpha=1;
    // Knots
    for(let k=0;k<4;k++){
      const kx=Math.random()*w, ky=Math.random()*h;
      const r=ctx.createRadialGradient(kx,ky,1,kx,ky,15+Math.random()*25);
      r.addColorStop(0,'rgba(70,30,5,.5)');
      r.addColorStop(1,'rgba(70,30,5,0)');
      ctx.fillStyle=r; ctx.fillRect(0,0,w,h);
    }
    const tex = new THREE.CanvasTexture(c);
    tex.wrapS=tex.wrapT=THREE.RepeatWrapping;
    tex.repeat.set(2.5,2.5);
    return tex;
  }

  // ── Show Level Intro ───────────────────────────────────────
  _showIntro(idx, name) {
    const el = document.getElementById('intro');
    document.getElementById('intro-num').textContent  = `Level ${idx+1}`;
    document.getElementById('intro-name').textContent = name;
    el.classList.add('on');
    setTimeout(()=>{ el.classList.remove('on');
      setTimeout(()=>{ this.state='playing'; }, 500);
    }, 2000);
  }

  // ── Physics ────────────────────────────────────────────────
  _physics(dt) {
    if(this.falling) {
      this.fallVY -= 16 * dt;
      this.fallY  += this.fallVY * dt;
      if(this.ball) {
        this.ball.position.y = BALL_R + this.fallY;
        if(this.state==='win') {
          const s = Math.max(0, 1 + this.fallY*2);
          this.ball.scale.setScalar(s);
        }
      }
      return;
    }

    // Input → target tilt
    let tx=0, tz=0;
    if(this.keys['ArrowUp']   ||this.keys['KeyW']) tx-=1;
    if(this.keys['ArrowDown'] ||this.keys['KeyS']) tx+=1;
    if(this.keys['ArrowLeft'] ||this.keys['KeyA']) tz+=1;
    if(this.keys['ArrowRight']||this.keys['KeyD']) tz-=1;

    if(tx&&tz) { tx*=.707; tz*=.707; } // normalize diagonal

    this.tTiltX = tx * MAX_TILT;
    this.tTiltZ = tz * MAX_TILT;

    // Smooth tilt
    const k = 1 - Math.pow(.001, dt * TILT_LAG);
    this.tiltX = lerp(this.tiltX, this.tTiltX, k);
    this.tiltZ = lerp(this.tiltZ, this.tTiltZ, k);
    this.boardGrp.rotation.x = this.tiltX;
    this.boardGrp.rotation.z = this.tiltZ;

    // Acceleration
    const ax =  GRAVITY_SCALE * Math.sin(this.tiltX);
    const az = -GRAVITY_SCALE * Math.sin(this.tiltZ);
    this.bvx += az * dt;
    this.bvz += ax * dt;

    // Friction (rolling resistance)
    const fric = Math.pow(FRICTION_K, dt * 60);
    this.bvx *= fric;
    this.bvz *= fric;

    // Speed cap
    const spd = Math.sqrt(this.bvx**2 + this.bvz**2);
    if(spd > MAX_SPEED) {
      this.bvx = (this.bvx/spd)*MAX_SPEED;
      this.bvz = (this.bvz/spd)*MAX_SPEED;
    }

    // Integrate
    let nx = this.bx + this.bvx * dt;
    let nz = this.bz + this.bvz * dt;

    // Wall collision
    const res = this._wallCollide(nx, nz);
    nx = res[0]; nz = res[1];

    this.bx = nx; this.bz = nz;

    // Rolling rotation
    if(this.ball && spd > .01) {
      const roll = (spd * dt) / BALL_R;
      const ax3 = new THREE.Vector3(-this.bvz/spd, 0, this.bvx/spd);
      this.ball.rotateOnWorldAxis(ax3, roll);
    }
    this.ball.position.set(this.bx, BALL_R, this.bz);

    // Edge fall
    const hw=this.boardW*.5-.01, hd=this.boardD*.5-.01;
    if(Math.abs(this.bx)>hw||Math.abs(this.bz)>hd) { this._die('edge'); return; }

    // Hole fall
    const gx = Math.floor((this.bx+this.boardW*.5)/CELL);
    const gz = Math.floor((this.bz+this.boardD*.5)/CELL);
    if(this.holeKeys.has(`${gx},${gz}`)) { this._die('hole'); return; }

    // Gem collection
    this.gemObjs.forEach((g,i)=>{
      if(g.collected) return;
      const dx=this.bx-g.wx, dz=this.bz-g.wz;
      if(dx*dx+dz*dz < (BALL_R+.28)**2) this._collectGem(i);
    });

    // Goal check
    if(this.goal && this.gemsGot>=this.gemsTotal) {
      const dx=this.bx-this.goal.wx, dz=this.bz-this.goal.wz;
      if(dx*dx+dz*dz < .4**2) this._win();
    }
  }

  _wallCollide(nx, nz) {
    const r = BALL_R;
    for(const w of this.wallBoxes) {
      const eMinX=w.minX-r, eMaxX=w.maxX+r;
      const eMinZ=w.minZ-r, eMaxZ=w.maxZ+r;
      if(nx>eMinX&&nx<eMaxX&&nz>eMinZ&&nz<eMaxZ) {
        const dL=nx-eMinX, dR=eMaxX-nx, dT=nz-eMinZ, dB=eMaxZ-nz;
        const m=Math.min(dL,dR,dT,dB);
        if(m===dL)  { nx=eMinX; this.bvx= Math.abs(this.bvx)*BOUNCE_K; }
        else if(m===dR) { nx=eMaxX; this.bvx=-Math.abs(this.bvx)*BOUNCE_K; }
        else if(m===dT) { nz=eMinZ; this.bvz= Math.abs(this.bvz)*BOUNCE_K; }
        else            { nz=eMaxZ; this.bvz=-Math.abs(this.bvz)*BOUNCE_K; }
      }
    }
    return [nx,nz];
  }

  // ── Events ─────────────────────────────────────────────────
  _collectGem(i) {
    const g = this.gemObjs[i];
    g.collected = true;
    this.gemsGot++;
    this._burst(g.mesh.position.clone());
    this.boardGrp.remove(g.mesh); g.mesh.geometry.dispose();
    this.boardGrp.remove(g.gl);
    // Flash
    const f=document.getElementById('gflash');
    f.style.opacity='1';
    setTimeout(()=>f.style.opacity='0', 100);
    this._updateHUD();

    // Goal hint
    if(this.gemsGot >= this.gemsTotal) {
      const msg=document.getElementById('gems-left-msg');
      msg.textContent='All gems collected! Reach the goal!';
      msg.style.color='#00ff88';
      msg.style.opacity='1';
      setTimeout(()=>msg.style.opacity='0', 2500);
    }
  }

  _die(reason) {
    if(this.state!=='playing') return;
    this.state='dead'; this.falling=true; this.fallVY=0; this.fallY=0;
    setTimeout(()=>{
      document.getElementById('ov-dead-time').textContent = formatTime(this.elapsed);
      document.getElementById('ov-dead-gems').textContent = `${this.gemsGot} / ${this.gemsTotal}`;
      document.getElementById('ov-dead-sub').textContent =
        reason==='hole'?'The ball fell into the void...':'The ball rolled off the edge!';
      document.getElementById('ov-dead').classList.add('on');
    }, 900);
  }

  _win() {
    if(this.state!=='playing') return;
    this.state='win'; this.falling=true; this.fallVY=0; this.fallY=0;
    this.bvx=0; this.bvz=0;
    setTimeout(()=>{
      document.getElementById('ov-win-time').textContent = formatTime(this.elapsed);
      document.getElementById('ov-win-gems').textContent = `${this.gemsGot} / ${this.gemsTotal}`;
      const subs=['The ball finds its way.','Precision and patience!','A perfect run!','Masterful control.','The maze bows to you.'];
      document.getElementById('ov-win-sub').textContent = subs[this.lvlIdx%subs.length];
      const btnNext = document.getElementById('btn-next');
      if(this.lvlIdx>=LEVELS.length-1) {
        btnNext.textContent='🎉 All Levels Complete!';
        btnNext.onclick=()=>this.loadLevel(0);
      } else {
        btnNext.textContent='Next Level →';
        btnNext.onclick=()=>this.nextLevel();
      }
      document.getElementById('ov-win').classList.add('on');
    }, 650);
  }

  nextLevel() {
    document.getElementById('ov-win').classList.remove('on');
    setTimeout(()=>this.loadLevel(Math.min(this.lvlIdx+1, LEVELS.length-1)), 300);
  }

  restartLevel() {
    document.getElementById('ov-win').classList.remove('on');
    document.getElementById('ov-dead').classList.remove('on');
    setTimeout(()=>this.loadLevel(this.lvlIdx), 200);
  }

  // ── Particles ──────────────────────────────────────────────
  _burst(pos) {
    const N=20;
    const g=new THREE.BufferGeometry();
    const pa=new Float32Array(N*3);
    const va=[];
    for(let i=0;i<N;i++){
      pa[i*3]=pos.x; pa[i*3+1]=pos.y; pa[i*3+2]=pos.z;
      const a=(i/N)*Math.PI*2;
      const s=1.8+Math.random()*2.5;
      va.push({x:Math.cos(a)*s,y:2.5+Math.random()*2.5,z:Math.sin(a)*s});
    }
    g.setAttribute('position',new THREE.BufferAttribute(pa,3));
    const m=new THREE.PointsMaterial({color:0x00e5ff,size:.14,transparent:true,opacity:1});
    const pts=new THREE.Points(g,m);
    this.boardGrp.add(pts);
    this.particles.push({pts,g,m,va,pa,life:1});
  }

  _tickParticles(dt) {
    for(let i=this.particles.length-1;i>=0;i--) {
      const p=this.particles[i];
      p.life-=dt*1.6;
      if(p.life<=0){this.boardGrp.remove(p.pts);this.particles.splice(i,1);continue;}
      p.va.forEach((v,j)=>{
        v.y-=5*dt;
        p.pa[j*3]  +=v.x*dt;
        p.pa[j*3+1]+=v.y*dt;
        p.pa[j*3+2]+=v.z*dt;
      });
      p.g.attributes.position.needsUpdate=true;
      p.m.opacity=Math.max(0,p.life);
    }
  }

  // ── Animations ─────────────────────────────────────────────
  _animate(t) {
    const ts = t*.001;
    // Gems float and spin
    this.gemObjs.forEach(g=>{
      if(g.collected) return;
      g.mesh.position.y = g.mesh.userData.baseY + Math.sin(ts*2+g.mesh.userData.phase)*.065;
      g.mesh.rotation.y += .018;
    });
    // Goal pulse
    if(this.goal) {
      const ready = this.gemsGot>=this.gemsTotal;
      const pulse = .6 + Math.sin(ts*3.5)*(ready?.6:.2);
      this.goal.gLight.intensity = ready ? pulse*1.8 : pulse*.5;
      this.goal.ring.material.emissiveIntensity = ready ? pulse*1.3 : .6;
      this.goal.disc.material.opacity = ready ? .5+Math.sin(ts*3.5)*.2 : .4;
    }
  }

  _updateHUD() {
    document.getElementById('hv-gems').textContent  = `${this.gemsGot}/${this.gemsTotal}`;
    document.getElementById('hv-timer').textContent = formatTime(this.elapsed);
  }

  // ── Main Loop ──────────────────────────────────────────────
  _loop(now) {
    requestAnimationFrame(t=>this._loop(t));
    const dt = Math.min((now-this.prevT)*.001, .05);
    this.prevT = now;

    if(this.state==='playing') {
      this.elapsed += dt;
      this._physics(dt);
      this._tickParticles(dt);
      this._animate(now);
      this._updateHUD();
      // Ball point light
      if(this.ball) {
        const wp = new THREE.Vector3();
        this.ball.getWorldPosition(wp);
        this.ballPt.position.copy(wp).y += 1;
      }
    } else if(this.state==='dead'||this.state==='win') {
      if(this.falling && this.ball) {
        this.fallVY -= (this.state==='win'?12:18)*dt;
        this.fallY  += this.fallVY*dt;
        this.ball.position.y = BALL_R + this.fallY;
        if(this.state==='win') this.ball.scale.setScalar(Math.max(0,1+this.fallY*2));
      }
      this._animate(now);
    } else {
      // intro
      this._animate(now);
    }

    // Camera follow tilt subtly
    const camX = -this.tiltZ*3;
    const camY = this.camBase.y - this.tiltX*2;
    this.camera.position.x = lerp(this.camera.position.x, camX,    .05);
    this.camera.position.y = lerp(this.camera.position.y, camY,     .05);
    this.camera.position.z = this.camBase.z;
    this.camera.lookAt(0,0,0);

    this.renderer.render(this.scene, this.camera);
  }
}

// ── Boot ───────────────────────────────────────────────────
window.addEventListener('load', ()=>{ window.game = new Game(); });
</script>
</body>
