</div>

<!-- Level intro -->
<div id="intro">
  <div id="intro-badge">Level <span id="intro-num">1</span></div>
  <div id="intro-name">The First Roll</div>
  <div id="intro-sub">Collect all gems, reach the goal.</div>
</div>

<!-- Gem flash -->
<div id="gflash"></div>

<!-- Status message -->
<div id="status-msg"></div>

<!-- Win overlay -->
<div class="overlay" id="ov-win">
  <div class="ocard">
    <div class="otitle" style="color:#00e5ff">✦ Level Complete!</div>
    <div class="osub" id="ov-win-sub">Well done!</div>
