  <div class="ocard">
    <div class="otitle" style="color:#ff5252">✕ Ball Lost!</div>
    <div class="osub" id="ov-dead-sub">The ball slipped away...</div>
    <div class="ostat"><span class="ostat-l">Survived</span><span class="ostat-v" style="color:#ffd54f" id="ov-dead-time">—</span></div>
    <div class="ostat"><span class="ostat-l">Gems Collected</span><span class="ostat-v" style="color:#00e5ff" id="ov-dead-gems">—</span></div>
    <button class="btn btn-red" id="btn-retry">↺ Try Again</button>
  </div>
</div>

<!-- Level dots -->
<div id="levelbar"></div>

<div id="hint">WASD / Arrow Keys — Tilt &nbsp;·&nbsp; R — Restart</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
'use strict';

// ═══════════════════════════════════════════════════════════════════
//  CONSTANTS
// ═══════════════════════════════════════════════════════════════════
const CELL    = 2.0;   // world units per grid cell
const WALL_H  = 0.58;  // wall height above board surface
const WALL_T  = 0.13;  // wall thickness
const BALL_R  = 0.235; // ball radius
const BD_T    = 0.22;  // board floor thickness
const GRAVITY  = 10.5; // m/s² on board surface
const FRICTION = 0.78; // velocity multiplier per frame at 60fps
const MAX_SPD  = 7.8;  // max ball speed
const MAX_TILT = 0.19; // max board tilt (~11°)
const TILT_SPD = 9.0;  // tilt response speed
const BOUNCE   = 0.15; // wall bounce coefficient

// ═══════════════════════════════════════════════════════════════════
//  LEVEL DATA
//  walls: {x,z,face}  face='e'(east/+x) | 's'(south/+z)
//  holes: [gx,gz]  — missing floor cell
//  gems:  [gx,gz]
//  start/goal: [gx,gz]
// ═══════════════════════════════════════════════════════════════════
const LEVELS = [

// ── 1: The First Roll ─────────────────────────────────────────────
{
  name:'The First Roll',
  hint:'Learn to tilt — ease in, ease out.',
  cols:7,rows:7,start:[1,1],goal:[5,5],
  gems:[[3,1],[5,2],[2,4]],
  holes:[],
  walls:[
    {x:2,z:1,face:'e'},
    {x:1,z:2,face:'s'},{x:2,z:2,face:'s'},
    {x:3,z:2,face:'e'},{x:4,z:2,face:'e'},
    {x:3,z:3,face:'s'},
    {x:4,z:3,face:'e'},{x:1,z:3,face:'e'},
    {x:2,z:4,face:'s'},{x:3,z:4,face:'e'},
    {x:4,z:4,face:'s'},{x:4,z:5,face:'e'},
  ]
},

// ── 2: Mind the Gap ───────────────────────────────────────────────
{
  name:'Mind the Gap',
  hint:'Holes are forever. Steer carefully.',
