const lerp  = (a,b,t) => a+(b-a)*t;
const clamp = (v,lo,hi) => Math.max(lo,Math.min(hi,v));
const fmtT  = t => { const s=Math.floor(t); return `${s}.${Math.floor((t-s)*10)}`; };

function showStatus(msg, color='#00ff88', dur=2000) {
  const el = document.getElementById('status-msg');
  el.textContent = msg;
  el.style.color = color;
  el.style.textShadow = `0 0 20px ${color}`;
  el.style.opacity = '1';
  clearTimeout(el._t);
  el._t = setTimeout(() => el.style.opacity='0', dur);
}

// ═══════════════════════════════════════════════════════════════════
//  GAME
// ═══════════════════════════════════════════════════════════════════
class Game {
  constructor() {
    this.lvl      = 0;
    this.state    = 'intro';  // intro|playing|dead|win
    this.elapsed  = 0;
    // tilt
    this.tX=0; this.tZ=0;    // current board rotation
    this.ttX=0; this.ttZ=0;  // target
    // ball
    this.bx=0; this.bz=0;
    this.bvx=0; this.bvz=0;
    this.falling=false; this.fvy=0; this.fy=0;
    // game data
    this.gems=[];  this.wallBoxes=[];
    this.holes=new Set();
    this.particles=[];
    this.gemsGot=0; this.gemsTotal=0;
    this.gemColl=[];
    // board dims
    this.bW=0; this.bD=0;
    // input
    this.keys={};
    this.prevT=0;

    this._initRenderer();
    this._initScene();
    this._initLights();
    this._initInput();
    this._initUI();
    this._buildLevelDots();
    this.loadLevel(0);
    requestAnimationFrame(t=>this._loop(t));
  }

  // ── Init ────────────────────────────────────────────────────
  _initRenderer() {
    const cvs = document.getElementById('c');
    this.R = new THREE.WebGLRenderer({canvas:cvs,antialias:true});
    this.R.setPixelRatio(Math.min(devicePixelRatio,2));
    this.R.setSize(innerWidth,innerHeight);
    this.R.shadowMap.enabled=true;
    this.R.shadowMap.type=THREE.PCFSoftShadowMap;
    this.R.outputEncoding=THREE.sRGBEncoding;
    this.R.toneMapping=THREE.ACESFilmicToneMapping;
    this.R.toneMappingExposure=1.08;
    addEventListener('resize',()=>{
      this.cam.aspect=innerWidth/innerHeight;
      this.cam.updateProjectionMatrix();
      this.R.setSize(innerWidth,innerHeight);
    });
  }

  _initScene() {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x05050d);
    this.scene.fog = new THREE.FogExp2(0x05050d,0.02);

    this.cam = new THREE.PerspectiveCamera(44,innerWidth/innerHeight,0.1,200);
    this.cam.position.set(0,20,16);
    this.cam.lookAt(0,0,0);
    this.camBase = this.cam.position.clone();

    this.grp = new THREE.Group();
    this.scene.add(this.grp);

    // Stars
    const sg=new THREE.BufferGeometry();
    const sv=new Float32Array(1400*3);
    for(let i=0;i<sv.length;i++) sv[i]=(Math.random()-.5)*160;
    sg.setAttribute('position',new THREE.BufferAttribute(sv,3));
    this.scene.add(new THREE.Points(sg,
      new THREE.PointsMaterial({color:0xffffff,size:0.16,transparent:true,opacity:0.5})));
  }

  _initLights() {
    this.scene.add(new THREE.AmbientLight(0x99aabb,0.5));

    const sun=new THREE.DirectionalLight(0xfff8e0,1.75);
    sun.position.set(10,24,12);
    sun.castShadow=true;
    sun.shadow.mapSize.set(2048,2048);
    const sc=sun.shadow.camera;
    sc.near=1;sc.far=75;sc.left=sc.bottom=-24;sc.right=sc.top=24;
    sun.shadow.bias=-0.0008;
    this.scene.add(sun); this.sun=sun;

    const fill=new THREE.DirectionalLight(0x3355ff,0.25);
    fill.position.set(-8,-4,-10);
    this.scene.add(fill);

    this.bPt=new THREE.PointLight(0xffffff,0.4,6);
    this.scene.add(this.bPt);
  }

  _initInput() {
    addEventListener('keydown',e=>{
      this.keys[e.code]=true;
      if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))
        e.preventDefault();
      if(e.code==='KeyR') this.restartLevel();
    });
    addEventListener('keyup',e=>this.keys[e.code]=false);
  }

  _initUI() {
    document.getElementById('btn-restart').onclick = ()=>this.restartLevel();
    document.getElementById('btn-retry').onclick   = ()=>this.restartLevel();
    document.getElementById('btn-replay-win').onclick = ()=>this.restartLevel();
    document.getElementById('btn-next').onclick    = ()=>this.nextLevel();
  }

  _buildLevelDots() {
    const bar = document.getElementById('levelbar');
    bar.innerHTML='';
    LEVELS.forEach((_,i)=>{
      const d=document.createElement('div');
      d.className='ldot';
      d.title=`Level ${i+1}: ${LEVELS[i].name}`;
      d.onclick=()=>{
        if(i<=this._maxUnlocked()) this.loadLevel(i);
      };
      d.id=`dot-${i}`;
      bar.appendChild(d);
    });
  }

  _maxUnlocked() {
    // Could track completed levels; for now allow all
    return LEVELS.length-1;
  }

  _updateDots() {
    LEVELS.forEach((_,i)=>{
      const d=document.getElementById(`dot-${i}`);
      if(!d) return;
      d.className='ldot'+(i<this.lvl?' done':i===this.lvl?' active':'');
    });
  }

  // ── Load Level ──────────────────────────────────────────────
  loadLevel(idx) {
    this.lvl=idx;
    const L=LEVELS[idx];

    // Dispose old
    while(this.grp.children.length){
      const c=this.grp.children[0];
      this.grp.remove(c);
      if(c.geometry) c.geometry.dispose();
      if(c.material) { const m=c.material; if(Array.isArray(m)) m.forEach(x=>x.dispose()); else m.dispose(); }
    }
    this.gems=[]; this.wallBoxes=[]; this.holes=new Set(); this.particles=[];

    const C=L.cols, R=L.rows;
    this.bW=C*CELL; this.bD=R*CELL;
    this.g2w=(gx,gz)=>({ wx:(gx+.5)*CELL-this.bW*.5, wz:(gz+.5)*CELL-this.bD*.5 });

    (L.holes||[]).forEach(([hx,hz])=>this.holes.add(`${hx},${hz}`));

    this._buildFloor(L);
    this._buildWalls(L);
    this._buildGems(L);
    this._buildGoal(L);
    this._buildBall(L);
    this._buildShadowCatcher();

    // Physics reset
    this.tX=0;this.tZ=0;this.ttX=0;this.ttZ=0;
    this.grp.rotation.set(0,0,0);
    this.bvx=0;this.bvz=0;
    this.falling=false;this.fvy=0;this.fy=0;
    this.gemsGot=0;this.gemsTotal=L.gems.length;
    this.gemColl=new Array(L.gems.length).fill(false);
    this.elapsed=0;this.state='intro';

    // Camera adapt to board size
    const dim=Math.max(C,R);
    const cd=dim*CELL*.88;
    this.camBase.set(0,cd,cd*.78);
    this.cam.position.copy(this.camBase);
    this.cam.lookAt(0,0,0);

    // Adapt sun shadow to board
    const sh=Math.max(this.bW,this.bD)*.6+4;
    const sc=this.sun.shadow.camera;
    sc.left=sc.bottom=-sh; sc.right=sc.top=sh;
    sc.updateProjectionMatrix();

    // UI
    document.getElementById('hv-level').textContent=idx+1;
    this._updateHUD();
    document.getElementById('ov-win').classList.remove('on');
    document.getElementById('ov-dead').classList.remove('on');
    document.getElementById('status-msg').style.opacity='0';
    this._updateDots();
    this._showIntro(idx,L.name,L.hint);
  }

  // ── Build Floor ────────────────────────────────────────────
  _buildFloor(L) {
    const tex=this._woodTex(512,512);
    const floorMat=new THREE.MeshStandardMaterial({map:tex,color:0xd0902a,roughness:.7,metalness:0});
    const edgeMat=new THREE.MeshStandardMaterial({color:0x5a2e0a,roughness:.82,metalness:.02});

    for(let gz=0;gz<L.rows;gz++) {
      for(let gx=0;gx<L.cols;gx++) {
        const {wx,wz}=this.g2w(gx,gz);
        if(this.holes.has(`${gx},${gz}`)) {
          // Hole visual: dark ring + void center
          const ring=new THREE.Mesh(
            new THREE.RingGeometry(CELL*.28,CELL*.45,20),
            new THREE.MeshBasicMaterial({color:0x1a0204,side:THREE.DoubleSide,transparent:true,opacity:.75})
          );
          ring.rotation.x=-Math.PI/2;
          ring.position.set(wx,.002,wz);
          this.grp.add(ring);
          const inner=new THREE.Mesh(
            new THREE.CircleGeometry(CELL*.26,20),
            new THREE.MeshBasicMaterial({color:0x000000,side:THREE.DoubleSide})
          );
          inner.rotation.x=-Math.PI/2;
          inner.position.set(wx,.001,wz);
          this.grp.add(inner);
        } else {
          const tile=new THREE.Mesh(
            new THREE.BoxGeometry(CELL-.025,BD_T,CELL-.025),
            floorMat
          );
          tile.position.set(wx,-BD_T*.5,wz);
          tile.receiveShadow=true;
          this.grp.add(tile);
        }
      }
    }
    // Under-plate
    const under=new THREE.Mesh(
      new THREE.BoxGeometry(this.bW+.5,BD_T*.55,this.bD+.5),
      edgeMat
    );
    under.position.set(0,-BD_T*1.28,0);
    this.grp.add(under);
  }

  // ── Build Walls ────────────────────────────────────────────
  _buildWalls(L) {
    const bW=this.bW, bD=this.bD, wy=WALL_H*.5;
    // Slightly darker top to give walls depth
    const topTex=this._woodTex(256,64);
    const wMat=new THREE.MeshStandardMaterial({color:0x6b3810,roughness:.62,metalness:.03});
    const wMat2=new THREE.MeshStandardMaterial({color:0x5a2e0a,roughness:.7,metalness:.02});

    const add=(x,y,z,sx,sy,sz,mat)=>{
      const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz), mat||wMat);
      m.position.set(x,y,z);
      m.castShadow=m.receiveShadow=true;
      this.grp.add(m);
      this.wallBoxes.push({minX:x-sx*.5,maxX:x+sx*.5,minZ:z-sz*.5,maxZ:z+sz*.5});
    };

    // Outer border (slightly thicker/taller)
    const OT=WALL_T*1.2, OH=WALL_H*1.1;
    add(0,OH*.5,-bD*.5-OT*.5, bW+OT*2,OH,OT, wMat2);
    add(0,OH*.5, bD*.5+OT*.5, bW+OT*2,OH,OT, wMat2);
    add(-bW*.5-OT*.5,OH*.5,0, OT,OH,bD, wMat2);
    add( bW*.5+OT*.5,OH*.5,0, OT,OH,bD, wMat2);

    // Interior
    (L.walls||[]).forEach(w=>{
      if(w.face==='e') {
        const wx=(w.x+1)*CELL-bW*.5;
        const wz=(w.z+.5)*CELL-bD*.5;
        add(wx,wy,wz, WALL_T,WALL_H,CELL+.015);
      } else if(w.face==='s') {
        const wx=(w.x+.5)*CELL-bW*.5;
        const wz=(w.z+1)*CELL-bD*.5;
        add(wx,wy,wz, CELL+.015,WALL_H,WALL_T);
      }
    });
  }

  // ── Shadow Catcher (invisible plane under board for shadow) ─
  _buildShadowCatcher() {
    const p=new THREE.Mesh(
      new THREE.PlaneGeometry(200,200),
      new THREE.ShadowMaterial({opacity:.35})
    );
    p.rotation.x=-Math.PI*.5;
    p.position.y=-BD_T*2;
    p.receiveShadow=true;
    this.grp.add(p);
  }

  // ── Build Gems ─────────────────────────────────────────────
  _buildGems(L) {
    (L.gems||[]).forEach(([gx,gz],i)=>{
      const {wx,wz}=this.g2w(gx,gz);
      const mat=new THREE.MeshStandardMaterial({
        color:0x00e5ff,emissive:0x00b0d4,emissiveIntensity:.9,
        roughness:.06,metalness:.2,transparent:true,opacity:.94
      });
      const mesh=new THREE.Mesh(new THREE.OctahedronGeometry(.235,0),mat);
      mesh.position.set(wx,.42,wz);
      mesh.castShadow=true;
      mesh.userData={baseY:.42,phase:Math.random()*Math.PI*2};
      this.grp.add(mesh);

      const gl=new THREE.PointLight(0x00d4ff,.6,3);
      gl.position.set(wx,.9,wz);
      this.grp.add(gl);

      this.gems.push({mesh,gl,wx,wz,collected:false});
    });
  }

  // ── Build Goal ─────────────────────────────────────────────
  _buildGoal(L) {
    const {wx,wz}=this.g2w(L.goal[0],L.goal[1]);

    // Outer glow ring
    const ring=new THREE.Mesh(
      new THREE.TorusGeometry(.42,.07,14,40),
      new THREE.MeshStandardMaterial({
        color:0x00ff88,emissive:0x00dd66,emissiveIntensity:1.3,
        roughness:.18,metalness:.4
      })
    );
    ring.rotation.x=Math.PI*.5;
    ring.position.set(wx,.03,wz);
    this.grp.add(ring);

    // Disc
    const disc=new THREE.Mesh(
      new THREE.CircleGeometry(.38,32),
      new THREE.MeshStandardMaterial({
        color:0x00cc55,emissive:0x00aa44,emissiveIntensity:.85,
        transparent:true,opacity:.65,side:THREE.DoubleSide
      })
    );
    disc.rotation.x=-Math.PI*.5;
    disc.position.set(wx,.02,wz);
    this.grp.add(disc);

    // Inner ring
    const inner=new THREE.Mesh(
      new THREE.TorusGeometry(.22,.04,10,32),
      new THREE.MeshStandardMaterial({
        color:0x00ff88,emissive:0x00ff88,emissiveIntensity:1.0,
        roughness:.1,metalness:.3
      })
    );
    inner.rotation.x=Math.PI*.5;
    inner.position.set(wx,.05,wz);
    this.grp.add(inner);

    const gl=new THREE.PointLight(0x00ff88,1.2,6);
    gl.position.set(wx,1.3,wz);
    this.grp.add(gl);

    this.goal={ring,disc,inner,gl,wx,wz};
  }

  // ── Build Ball ─────────────────────────────────────────────
  _buildBall(L) {
    const {wx,wz}=this.g2w(L.start[0],L.start[1]);
    const geo=new THREE.SphereGeometry(BALL_R,42,42);
    const mat=new THREE.MeshStandardMaterial({
      color:0xe0e2ef,roughness:.11,metalness:.96,envMapIntensity:.9
    });
    this.ball=new THREE.Mesh(geo,mat);
    this.ball.castShadow=true;
    this.ball.position.set(wx,BALL_R,wz);
    this.grp.add(this.ball);
    this.bx=wx; this.bz=wz;
    this.ball.scale.setScalar(1);
  }

  // ── Wood Texture ───────────────────────────────────────────
  _woodTex(w,h) {
    const cv=document.createElement('canvas');
    cv.width=w; cv.height=h;
    const ctx=cv.getContext('2d');
    ctx.fillStyle='#c88820';
    ctx.fillRect(0,0,w,h);
    const cols=['#9e6010','#b07018','#c08820','#d09828','#b87820','#a86810'];
    for(let i=0;i<90;i++) {
      const y=(i/90)*h;
      const a=2+Math.random()*12;
      const f=.006+Math.random()*.02;
      ctx.beginPath();
      ctx.lineWidth=.3+Math.random()*2.2;
      ctx.strokeStyle=cols[i%cols.length];
      ctx.globalAlpha=.15+Math.random()*.35;
      for(let x=0;x<w;x++) {
        const cy=y+Math.sin(x*f+i*.25)*a+Math.sin(x*.025)*4;
        x===0?ctx.moveTo(x,cy):ctx.lineTo(x,cy);
      }
      ctx.stroke();
    }
    ctx.globalAlpha=1;
    for(let k=0;k<5;k++) {
      const kx=Math.random()*w, ky=Math.random()*h;
      const gr=ctx.createRadialGradient(kx,ky,1,kx,ky,12+Math.random()*30);
      gr.addColorStop(0,'rgba(60,25,5,.55)');
      gr.addColorStop(1,'rgba(60,25,5,0)');
      ctx.fillStyle=gr; ctx.fillRect(0,0,w,h);
    }
    const tex=new THREE.CanvasTexture(cv);
    tex.wrapS=tex.wrapT=THREE.RepeatWrapping;
    tex.repeat.set(2.8,2.8);
    return tex;
  }

  // ── Show Intro ─────────────────────────────────────────────
  _showIntro(idx,name,hint) {
    const el=document.getElementById('intro');
    document.getElementById('intro-num').textContent=idx+1;
    document.getElementById('intro-name').textContent=name;
    document.getElementById('intro-sub').textContent=hint||'Collect all gems, reach the goal.';
    el.classList.add('on');
    setTimeout(()=>{
      el.classList.remove('on');
      setTimeout(()=>{ this.state='playing'; },500);
    },2200);
  }

  // ── Physics ────────────────────────────────────────────────
  _physics(dt) {
    if(this.falling) {
      this.fvy -= (this.state==='win'?13:18)*dt;
      this.fy  += this.fvy*dt;
      if(this.ball) {
        this.ball.position.y=BALL_R+this.fy;
        if(this.state==='win') this.ball.scale.setScalar(Math.max(0,1+this.fy*2.5));
      }
      return;
    }

    // Input
    let tx=0, tz=0;
    if(this.keys['ArrowUp']   ||this.keys['KeyW']) tx-=1;
    if(this.keys['ArrowDown'] ||this.keys['KeyS']) tx+=1;
    if(this.keys['ArrowLeft'] ||this.keys['KeyA']) tz+=1;
    if(this.keys['ArrowRight']||this.keys['KeyD']) tz-=1;
    if(tx&&tz){tx*=.7071;tz*=.7071;}

    this.ttX=tx*MAX_TILT;
    this.ttZ=tz*MAX_TILT;

    // Smooth tilt (exponential approach)
    const k=1-Math.pow(.001,dt*TILT_SPD);
    this.tX=lerp(this.tX,this.ttX,k);
    this.tZ=lerp(this.tZ,this.ttZ,k);
    this.grp.rotation.x=this.tX;
    this.grp.rotation.z=this.tZ;

    // Gravity on tilted plane → ball acceleration
    this.bvx += -GRAVITY*Math.sin(this.tZ)*dt;
    this.bvz +=  GRAVITY*Math.sin(this.tX)*dt;

    // Friction (velocity damping)
    const fr=Math.pow(FRICTION,dt*60);
    this.bvx*=fr; this.bvz*=fr;

    // Speed cap
    const spd=Math.hypot(this.bvx,this.bvz);
    if(spd>MAX_SPD){ const s=MAX_SPD/spd; this.bvx*=s; this.bvz*=s; }

    // Integrate position
    let nx=this.bx+this.bvx*dt;
    let nz=this.bz+this.bvz*dt;

    // Wall collision
    [nx,nz]=this._collide(nx,nz);
    this.bx=nx; this.bz=nz;

    // Rolling rotation visual
    if(spd>.02) {
      const roll=spd*dt/BALL_R;
      this.ball.rotateOnWorldAxis(
        new THREE.Vector3(-this.bvz/spd,0,this.bvx/spd).normalize(), roll
      );
    }
    this.ball.position.set(this.bx,BALL_R,this.bz);

    // ── Edge detect
    const hw=this.bW*.5-BALL_R*.6, hd=this.bD*.5-BALL_R*.6;
    if(Math.abs(this.bx)>hw||Math.abs(this.bz)>hd){this._die('edge');return;}

    // ── Hole detect
    const gx=Math.floor((this.bx+this.bW*.5)/CELL);
    const gz=Math.floor((this.bz+this.bD*.5)/CELL);
    if(this.holes.has(`${gx},${gz}`)){this._die('hole');return;}

    // ── Gem collect
    for(let i=0;i<this.gems.length;i++){
      if(this.gemColl[i]) continue;
      const g=this.gems[i];
      if((this.bx-g.wx)**2+(this.bz-g.wz)**2 < (BALL_R+.3)**2)
        this._collect(i);
    }

    // ── Goal
    if(this.goal && this.gemsGot>=this.gemsTotal) {
      if((this.bx-this.goal.wx)**2+(this.bz-this.goal.wz)**2 < .42**2)
        this._win();
    }
  }

  _collide(nx,nz) {
    const r=BALL_R;
    for(const w of this.wallBoxes) {
      const eX0=w.minX-r,eX1=w.maxX+r,eZ0=w.minZ-r,eZ1=w.maxZ+r;
      if(nx>eX0&&nx<eX1&&nz>eZ0&&nz<eZ1) {
        const dL=nx-eX0,dR=eX1-nx,dT=nz-eZ0,dB=eZ1-nz;
        const m=Math.min(dL,dR,dT,dB);
        if(m===dL)      {nx=eX0; this.bvx= Math.abs(this.bvx)*BOUNCE;}
        else if(m===dR) {nx=eX1; this.bvx=-Math.abs(this.bvx)*BOUNCE;}
        else if(m===dT) {nz=eZ0; this.bvz= Math.abs(this.bvz)*BOUNCE;}
        else            {nz=eZ1; this.bvz=-Math.abs(this.bvz)*BOUNCE;}
      }
    }
    return [nx,nz];
  }

  // ── Gem collect ─────────────────────────────────────────────
  _collect(i) {
    this.gemColl[i]=true;
    const g=this.gems[i];
    g.collected=true;
    this.gemsGot++;
    this._burst(g.mesh.position.clone());
    this.grp.remove(g.mesh); g.mesh.geometry.dispose();
    this.grp.remove(g.gl);

    // flash
    const f=document.getElementById('gflash');
    f.style.opacity='1';
    clearTimeout(f._t); f._t=setTimeout(()=>f.style.opacity='0',110);

    this._updateHUD();

    const rem=this.gemsTotal-this.gemsGot;
    if(rem===0) showStatus('All gems collected! Find the goal!','#00ff88',2500);
    else if(rem===1) showStatus('Last gem!','#00e5ff',1500);
  }

  // ── Die ─────────────────────────────────────────────────────
  _die(reason) {
    if(this.state!=='playing') return;
    this.state='dead'; this.falling=true; this.fvy=0; this.fy=0;
    setTimeout(()=>{
      document.getElementById('ov-dead-time').textContent=fmtT(this.elapsed);
      document.getElementById('ov-dead-gems').textContent=`${this.gemsGot} / ${this.gemsTotal}`;
      document.getElementById('ov-dead-sub').textContent=
        reason==='hole'?'The ball fell into the void...':'The ball rolled off the edge!';
      document.getElementById('ov-dead').classList.add('on');
    },900);
  }

  // ── Win ─────────────────────────────────────────────────────
  _win() {
    if(this.state!=='playing') return;
    this.state='win'; this.falling=true; this.fvy=0; this.fy=0;
    this.bvx=0; this.bvz=0;
    setTimeout(()=>{
      document.getElementById('ov-win-time').textContent=fmtT(this.elapsed);
      document.getElementById('ov-win-gems').textContent=`${this.gemsGot} / ${this.gemsTotal}`;
      const subs=['The ball finds its way.','Precision and patience!','A perfect run!',
                  'Masterful control.','The maze yields to you.','Smooth as silk!',
                  'Brilliant navigation!','Well played!'];
      document.getElementById('ov-win-sub').textContent=subs[this.lvl%subs.length];
      const btn=document.getElementById('btn-next');
      if(this.lvl>=LEVELS.length-1) {
        btn.textContent='🏆 You Beat All Levels!';
        btn.onclick=()=>this.loadLevel(0);
      } else {
        btn.textContent='Next Level →';
        btn.onclick=()=>this.nextLevel();
      }
      document.getElementById('ov-win').classList.add('on');
    },700);
  }

  nextLevel() {
    document.getElementById('ov-win').classList.remove('on');
    setTimeout(()=>this.loadLevel(Math.min(this.lvl+1,LEVELS.length-1)),300);
  }

  restartLevel() {
    document.getElementById('ov-win').classList.remove('on');
    document.getElementById('ov-dead').classList.remove('on');
    setTimeout(()=>this.loadLevel(this.lvl),200);
  }

  // ── Particles ───────────────────────────────────────────────
  _burst(pos) {
    const N=22;
    const g=new THREE.BufferGeometry();
    const pa=new Float32Array(N*3);
    const va=[];
    for(let i=0;i<N;i++){
      pa[i*3]=pos.x; pa[i*3+1]=pos.y; pa[i*3+2]=pos.z;
      const a=(i/N)*Math.PI*2;
      const s=2+Math.random()*3;
      va.push({x:Math.cos(a)*s,y:2.8+Math.random()*3,z:Math.sin(a)*s});
    }
    g.setAttribute('position',new THREE.BufferAttribute(pa,3));
    const m=new THREE.PointsMaterial({color:0x00e5ff,size:.15,transparent:true,opacity:1});
    const pts=new THREE.Points(g,m);
    this.grp.add(pts);
    this.particles.push({pts,g,m,va,pa,life:1});
  }

  _tickPFX(dt) {
    for(let i=this.particles.length-1;i>=0;i--) {
      const p=this.particles[i];
      p.life-=dt*1.6;
      if(p.life<=0){this.grp.remove(p.pts);this.particles.splice(i,1);continue;}
      p.va.forEach((v,j)=>{
        v.y-=6*dt;
        p.pa[j*3]+=v.x*dt; p.pa[j*3+1]+=v.y*dt; p.pa[j*3+2]+=v.z*dt;
      });
      p.g.attributes.position.needsUpdate=true;
      p.m.opacity=Math.max(0,p.life);
    }
  }

  // ── Gem/Goal Animation ──────────────────────────────────────
  _animWorld(ts) {
    for(const g of this.gems){
      if(g.collected) continue;
      g.mesh.position.y=g.mesh.userData.baseY+Math.sin(ts*2.1+g.mesh.userData.phase)*.07;
      g.mesh.rotation.y+=.019;
    }
    if(this.goal){
      const ready=this.gemsGot>=this.gemsTotal;
      const p=.6+Math.sin(ts*3.5)*(ready?.65:.18);
      this.goal.gl.intensity=ready?p*1.9:.5;
      this.goal.ring.material.emissiveIntensity=ready?p*1.3:.55;
      this.goal.disc.material.opacity=ready?.45+Math.sin(ts*3.5)*.2:.35;
      this.goal.inner.rotation.y+=.024;
      this.goal.inner.material.emissiveIntensity=ready?p*1.2:.4;
    }
  }

  // ── HUD ─────────────────────────────────────────────────────
  _updateHUD() {
    document.getElementById('hv-gems').textContent =`${this.gemsGot}/${this.gemsTotal}`;
    document.getElementById('hv-timer').textContent=fmtT(this.elapsed);
  }

  // ── Main Loop ───────────────────────────────────────────────
  _loop(now) {
    requestAnimationFrame(t=>this._loop(t));
    const dt=Math.min((now-this.prevT)*.001,.05);
    this.prevT=now;
    const ts=now*.001;

    if(this.state==='playing') {
      this.elapsed+=dt;
      this._physics(dt);
      this._tickPFX(dt);
      this._animWorld(ts);
      this._updateHUD();
      if(this.ball) {
        const wp=new THREE.Vector3();
        this.ball.getWorldPosition(wp);
        this.bPt.position.copy(wp).y+=1.2;
      }
    } else if(this.state==='dead'||this.state==='win') {
      if(this.falling&&this.ball){
        this.fvy-=(this.state==='win'?13:18)*dt;
        this.fy+=this.fvy*dt;
        this.ball.position.y=BALL_R+this.fy;
        if(this.state==='win') this.ball.scale.setScalar(Math.max(0,1+this.fy*2.5));
      }
      this._animWorld(ts);
    } else {
      this._animWorld(ts);
    }

    // Camera: subtle tilt follow
    const tCamX=-this.tZ*3.5;
    const tCamY=this.camBase.y-this.tX*2.5;
    this.cam.position.x=lerp(this.cam.position.x,tCamX,.06);
    this.cam.position.y=lerp(this.cam.position.y,tCamY,.06);
    this.cam.position.z=this.camBase.z;
    this.cam.lookAt(0,0,0);

    this.R.render(this.scene,this.cam);
  }
}

// ── Boot ──────────────────────────────────────────────────────
window.addEventListener('load',()=>{ window.game=new Game(); });
</script>
</body>
</html>
