/* ── CONTROLS HINT ───────────────────────────────────── */
#hint{
  position:fixed;bottom:18px;left:50%;transform:translateX(-50%);
  font-size:11px;letter-spacing:.08em;color:rgba(255,255,255,.25);
  pointer-events:none;z-index:10
}

/* ── LEVEL SELECT ────────────────────────────────────── */
#levelbar{
  position:fixed;bottom:0;left:0;right:0;
  display:flex;justify-content:center;align-items:center;gap:6px;
  padding:10px;pointer-events:none;z-index:15;opacity:.5;
  transition:opacity .2s
}
#levelbar:hover{opacity:1}
.ldot{
  width:8px;height:8px;border-radius:50%;
  background:rgba(255,255,255,.25);cursor:pointer;
  pointer-events:auto;transition:all .2s;border:1px solid transparent
}
.ldot.done{background:rgba(0,229,255,.7)}
.ldot.active{background:#fff;transform:scale(1.3);border-color:rgba(255,255,255,.5)}
</style>
</head>
