<canvas id="c"></canvas>

<!-- HUD -->
<div id="hud">
  <div class="hcard"><div class="hlabel">Level</div><div class="hval" id="hv-level">1</div></div>
  <div class="hcard"><div class="hlabel">Gems</div><div class="hval" id="hv-gems">0/0</div></div>
  <div class="hcard"><div class="hlabel">Time</div><div class="hval" id="hv-timer">0.0</div></div>
  <div class="hcard"><button id="btn-restart">↺ Restart</button></div>
</div>

<!-- Level intro -->
<div id="intro">
  <div id="intro-badge">Level <span id="intro-num">1</span></div>
  <div id="intro-name">The First Roll</div>
  <div id="intro-sub">Collect all gems, reach the goal.</div>
</div>

<!-- Gem flash -->
<div id="gflash"></div>

<!-- Status message -->
<div id="status-msg"></div>

<!-- Win overlay -->
<div class="overlay" id="ov-win">
  <div class="ocard">
    <div class="otitle" style="color:#00e5ff">✦ Level Complete!</div>
    <div class="osub" id="ov-win-sub">Well done!</div>
    <div class="ostat"><span class="ostat-l">Time</span><span class="ostat-v" style="color:#ffd54f" id="ov-win-time">—</span></div>
    <div class="ostat"><span class="ostat-l">Gems Collected</span><span class="ostat-v" style="color:#00e5ff" id="ov-win-gems">—</span></div>
    <button class="btn btn-blue" id="btn-next">Next Level →</button><br>
    <button class="btn btn-ghost" id="btn-replay-win">Replay Level</button>
  </div>
</div>

<!-- Game over overlay -->
<div class="overlay" id="ov-dead">
  <div class="ocard">
    <div class="otitle" style="color:#ff5252">✕ Ball Lost!</div>
