    <button class="btn btn-red" id="btn-retry">↺ Try Again</button>
  </div>
</div>

<!-- Level dots -->
<div id="levelbar"></div>

<div id="hint">WASD / Arrow Keys — Tilt &nbsp;·&nbsp; R — Restart</div>

