   885	    if(this.keys['ArrowDown'] ||this.keys['KeyS']) tx+=1;
   886	    if(this.keys['ArrowLeft'] ||this.keys['KeyA']) tz+=1;
   887	    if(this.keys['ArrowRight']||this.keys['KeyD']) tz-=1;
