   905	    const fr=Math.pow(FRICTION,dt*60);
   906	    this.bvx*=fr; this.bvz*=fr;
   907	
   908	    // Speed cap
   909	    const spd=Math.hypot(this.bvx,this.bvz);
   910	    if(spd>MAX_SPD){ const s=MAX_SPD/spd; this.bvx*=s; this.bvz*=s; }
